package com.activitynotifier;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

/**
 * Config keys are a permanent contract (see specs/done/001-activity-detection/contracts/config.md,
 * specs/done/002-damage-notifier/contracts/config.md and specs/done/003-custom-animation-ids/contracts/config.md).
 * Never rename a keyName without a migration.
 */
@ConfigGroup(ActivityNotifierConfig.GROUP)
public interface ActivityNotifierConfig extends Config
{
	String GROUP = "activitynotifier";

	// region Sections

	@ConfigSection(
		name = "General",
		description = "General settings",
		position = 0
	)
	String generalSection = "general";

	@ConfigSection(
		name = "Signals",
		description = "How signals are delivered (e.g. to the Watchdog plugin) and their text",
		position = 10
	)
	String signalsSection = "signals";

	@ConfigSection(
		name = "General detectors",
		description = "Broad activity detectors, each individually toggleable",
		position = 20
	)
	String generalDetectorsSection = "generalDetectors";

	@ConfigSection(
		name = "Specific activities",
		description = "Individually watched activities",
		position = 30
	)
	String specificActivitiesSection = "specificActivities";

	@ConfigSection(
		name = "Extra delays",
		description = "Extra time added to the base delay before a detector counts as stopped",
		position = 40,
		closedByDefault = true
	)
	String delaysSection = "delays";

	@ConfigSection(
		name = "Resource alerts",
		description = "Alerts when a resource crosses a threshold, with a matching recovered signal",
		position = 50,
		closedByDefault = true
	)
	String resourcesSection = "resources";

	@ConfigSection(
		name = "Damage taken",
		description = "Alerts when you take damage",
		position = 55,
		closedByDefault = true
	)
	String damageSection = "damage";

	@ConfigSection(
		name = "Logout warnings",
		description = "Warnings before you are logged out",
		position = 60,
		closedByDefault = true
	)
	String logoutSection = "logout";

	// endregion

	// region General

	@ConfigItem(
		keyName = "showSidePanel",
		name = "Show side panel",
		description = "Show the Activity Notifier button in the sidebar",
		position = 0,
		section = generalSection
	)
	default boolean showSidePanel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pauseHotkey",
		name = "Pause hotkey",
		description = "Pauses or resumes detection. Pausing while inactive sends an active signal",
		position = 1,
		section = generalSection
	)
	default Keybind pauseHotkey()
	{
		return Keybind.NOT_SET;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "baseDelay",
		name = "Base delay",
		description = "How long no activity must be seen before you count as inactive, before extra delays",
		position = 2,
		section = generalSection
	)
	default int baseDelay()
	{
		return 2000;
	}

	// endregion

	// region Signals

	@ConfigItem(
		keyName = "chatSignals",
		name = "Chat messages",
		description = "Send signals as filtered game messages in the chat box, hidden when the Game chat filter is set to Filtered (Watchdog: Game Message alert, message type Spam or Any)",
		position = 0,
		section = signalsSection
	)
	default boolean chatSignals()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notificationSignals",
		name = "RuneLite notification",
		description = "Send signals as RuneLite notifications (Watchdog: Notification Fired alert)",
		position = 1,
		section = signalsSection
	)
	default Notification notificationSignals()
	{
		return Notification.OFF;
	}

	@ConfigItem(
		keyName = "reminderEnabled",
		name = "Inactive reminders",
		description = "Repeat a 'Still inactive' signal while you stay inactive",
		position = 2,
		section = signalsSection
	)
	default boolean reminderEnabled()
	{
		return false;
	}

	@Range(min = 10)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "reminderInterval",
		name = "Reminder interval",
		description = "Time between 'Still inactive' reminders",
		position = 3,
		section = signalsSection
	)
	default int reminderInterval()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "templateInactive",
		name = "Inactive text",
		description = "Detail after 'Activity Notifier: Inactive - '. Tokens: {activity}",
		position = 4,
		section = signalsSection
	)
	default String templateInactive()
	{
		return "{activity}";
	}

	@ConfigItem(
		keyName = "templateActive",
		name = "Active text",
		description = "Detail after 'Activity Notifier: Active - '. Tokens: {activity}, {duration}",
		position = 5,
		section = signalsSection
	)
	default String templateActive()
	{
		return "{activity} (inactive for {duration})";
	}

	@ConfigItem(
		keyName = "templateReminder",
		name = "Reminder text",
		description = "Detail after 'Activity Notifier: Still inactive - '. Tokens: {activity}, {duration}",
		position = 6,
		section = signalsSection
	)
	default String templateReminder()
	{
		return "{activity} (for {duration})";
	}

	@ConfigItem(
		keyName = "templateResourceAlert",
		name = "Resource alert text",
		description = "Detail for resource alerts. Tokens: {resource}, {value}, {threshold}",
		position = 7,
		section = signalsSection
	)
	default String templateResourceAlert()
	{
		return "{value} (threshold {threshold})";
	}

	@ConfigItem(
		keyName = "templateResourceRecovered",
		name = "Resource recovered text",
		description = "Detail for resource recovered signals. Tokens: {resource}, {value}",
		position = 8,
		section = signalsSection
	)
	default String templateResourceRecovered()
	{
		return "{value}";
	}

	@ConfigItem(
		keyName = "templateIdleLogout",
		name = "Idle logout text",
		description = "Detail for the idle logout warning",
		position = 9,
		section = signalsSection
	)
	default String templateIdleLogout()
	{
		return "About to log out from idling";
	}

	@ConfigItem(
		keyName = "templateSixHour",
		name = "Six hour logout text",
		description = "Detail for the six hour logout warning",
		position = 10,
		section = signalsSection
	)
	default String templateSixHour()
	{
		return "About to reach the six hour limit";
	}

	@ConfigItem(
		keyName = "templateDamageTaken",
		name = "Damage taken text",
		description = "Detail for damage taken signals. Tokens: {damage}, {threshold}, {hitpoints}",
		position = 11,
		section = signalsSection
	)
	default String templateDamageTaken()
	{
		return "{damage}";
	}

	// endregion

	// region General detectors

	@ConfigItem(
		keyName = "detectAnimation",
		name = "Animation",
		description = "Skilling and action animations count as activity",
		position = 0,
		section = generalDetectorsSection
	)
	default boolean detectAnimation()
	{
		return true;
	}

	@ConfigItem(
		keyName = "customAnimationIds",
		name = "Custom animation IDs",
		description = "Comma-separated animation IDs that also count as animation activity, e.g. 5216, 13149. The side panel shows your last animation's ID",
		position = 1,
		section = generalDetectorsSection
	)
	default String customAnimationIds()
	{
		return "";
	}

	@ConfigItem(
		keyName = "detectInteraction",
		name = "Interaction",
		description = "Interacting with NPCs (including combat targets and fishing spots) counts as activity",
		position = 2,
		section = generalDetectorsSection
	)
	default boolean detectInteraction()
	{
		return true;
	}

	@ConfigItem(
		keyName = "detectMovement",
		name = "Movement",
		description = "Walking and running count as activity",
		position = 3,
		section = generalDetectorsSection
	)
	default boolean detectMovement()
	{
		return false;
	}

	@ConfigItem(
		keyName = "detectXpGain",
		name = "XP gain",
		description = "Gaining XP counts as activity",
		position = 4,
		section = generalDetectorsSection
	)
	default boolean detectXpGain()
	{
		return true;
	}

	@Range(min = 1)
	@ConfigItem(
		keyName = "xpThreshold",
		name = "XP gain threshold",
		description = "Minimum XP in a single drop for the XP gain detector to count it",
		position = 5,
		section = generalDetectorsSection
	)
	default int xpThreshold()
	{
		return 1;
	}

	// endregion

	// region Specific activities

	@ConfigItem(keyName = "detectCooking", name = "Cooking", description = "Watch Cooking", position = 0, section = specificActivitiesSection)
	default boolean detectCooking()
	{
		return false;
	}

	@ConfigItem(keyName = "detectCrafting", name = "Crafting", description = "Watch Crafting", position = 1, section = specificActivitiesSection)
	default boolean detectCrafting()
	{
		return false;
	}

	@ConfigItem(keyName = "detectFishing", name = "Fishing", description = "Watch Fishing", position = 2, section = specificActivitiesSection)
	default boolean detectFishing()
	{
		return false;
	}

	@ConfigItem(keyName = "detectFiremaking", name = "Firemaking", description = "Watch Firemaking", position = 3, section = specificActivitiesSection)
	default boolean detectFiremaking()
	{
		return false;
	}

	@ConfigItem(keyName = "detectFletching", name = "Fletching", description = "Watch Fletching", position = 4, section = specificActivitiesSection)
	default boolean detectFletching()
	{
		return false;
	}

	@ConfigItem(keyName = "detectHerblore", name = "Herblore", description = "Watch Herblore", position = 5, section = specificActivitiesSection)
	default boolean detectHerblore()
	{
		return false;
	}

	@ConfigItem(keyName = "detectMining", name = "Mining", description = "Watch Mining", position = 6, section = specificActivitiesSection)
	default boolean detectMining()
	{
		return false;
	}

	@ConfigItem(keyName = "detectWoodcutting", name = "Woodcutting", description = "Watch Woodcutting", position = 7, section = specificActivitiesSection)
	default boolean detectWoodcutting()
	{
		return false;
	}

	@ConfigItem(keyName = "detectSmithing", name = "Smithing", description = "Watch Smithing", position = 8, section = specificActivitiesSection)
	default boolean detectSmithing()
	{
		return false;
	}

	@ConfigItem(keyName = "detectSailing", name = "Sailing (beta)", description = "Beta: not fully tested yet. Watch Sailing, including steering a ship", position = 9, section = specificActivitiesSection)
	default boolean detectSailing()
	{
		return false;
	}

	@ConfigItem(keyName = "detectCombat", name = "Combat", description = "Watch combat (accounts for weapon attack speed)", position = 10, section = specificActivitiesSection)
	default boolean detectCombat()
	{
		return false;
	}

	@ConfigItem(keyName = "detectMagicSkilling", name = "Magic skilling", description = "Watch skilling spells such as Lunar crafting spells", position = 11, section = specificActivitiesSection)
	default boolean detectMagicSkilling()
	{
		return false;
	}

	// endregion

	// region Extra delays

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayAnimation", name = "Animation", description = "Extra delay for the animation detector", position = 0, section = delaysSection)
	default int delayAnimation()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayInteraction", name = "Interaction", description = "Extra delay for the interaction detector", position = 1, section = delaysSection)
	default int delayInteraction()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayMovement", name = "Movement (grace)", description = "Grace delay after you stop walking or running", position = 2, section = delaysSection)
	default int delayMovement()
	{
		return 2000;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayXpGain", name = "XP gain", description = "Extra delay for the XP gain detector", position = 3, section = delaysSection)
	default int delayXpGain()
	{
		return 3000;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayCooking", name = "Cooking", description = "Extra delay for Cooking", position = 10, section = delaysSection)
	default int delayCooking()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayCrafting", name = "Crafting", description = "Extra delay for Crafting", position = 11, section = delaysSection)
	default int delayCrafting()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayFishing", name = "Fishing", description = "Extra delay for Fishing", position = 12, section = delaysSection)
	default int delayFishing()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayFiremaking", name = "Firemaking", description = "Extra delay for Firemaking", position = 13, section = delaysSection)
	default int delayFiremaking()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayFletching", name = "Fletching", description = "Extra delay for Fletching", position = 14, section = delaysSection)
	default int delayFletching()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayHerblore", name = "Herblore", description = "Extra delay for Herblore", position = 15, section = delaysSection)
	default int delayHerblore()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayMining", name = "Mining", description = "Extra delay for Mining", position = 16, section = delaysSection)
	default int delayMining()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayWoodcutting", name = "Woodcutting", description = "Extra delay for Woodcutting", position = 17, section = delaysSection)
	default int delayWoodcutting()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delaySmithing", name = "Smithing", description = "Extra delay for Smithing", position = 18, section = delaysSection)
	default int delaySmithing()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delaySailing", name = "Sailing (beta)", description = "Beta: not fully tested yet. Extra delay for Sailing", position = 19, section = delaysSection)
	default int delaySailing()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayCombat", name = "Combat", description = "Extra delay for combat, added on top of your weapon's attack interval", position = 20, section = delaysSection)
	default int delayCombat()
	{
		return 0;
	}

	@Range(min = 0)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "delayMagicSkilling", name = "Magic skilling", description = "Extra delay for magic skilling", position = 21, section = delaysSection)
	default int delayMagicSkilling()
	{
		return 0;
	}

	// endregion

	// region Resource alerts

	@ConfigItem(keyName = "alertHitpoints", name = "Low hitpoints", description = "Alert when hitpoints drop to or below the threshold", position = 0, section = resourcesSection)
	default boolean alertHitpoints()
	{
		return false;
	}

	@Range(min = 0)
	@ConfigItem(keyName = "hitpointsThreshold", name = "Hitpoints threshold", description = "Hitpoints threshold", position = 1, section = resourcesSection)
	default int hitpointsThreshold()
	{
		return 10;
	}

	@ConfigItem(keyName = "alertPrayer", name = "Low prayer", description = "Alert when prayer drops to or below the threshold", position = 2, section = resourcesSection)
	default boolean alertPrayer()
	{
		return false;
	}

	@Range(min = 0)
	@ConfigItem(keyName = "prayerThreshold", name = "Prayer threshold", description = "Prayer threshold", position = 3, section = resourcesSection)
	default int prayerThreshold()
	{
		return 10;
	}

	@ConfigItem(keyName = "alertLowEnergy", name = "Low run energy", description = "Alert when run energy drops to or below the threshold", position = 4, section = resourcesSection)
	default boolean alertLowEnergy()
	{
		return false;
	}

	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(keyName = "lowEnergyThreshold", name = "Low run energy threshold", description = "Low run energy threshold", position = 5, section = resourcesSection)
	default int lowEnergyThreshold()
	{
		return 10;
	}

	@ConfigItem(keyName = "alertHighEnergy", name = "Run energy restored", description = "Alert when run energy rises to or above the threshold", position = 6, section = resourcesSection)
	default boolean alertHighEnergy()
	{
		return false;
	}

	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(keyName = "highEnergyThreshold", name = "Restored run energy threshold", description = "Restored run energy threshold", position = 7, section = resourcesSection)
	default int highEnergyThreshold()
	{
		return 90;
	}

	@ConfigItem(keyName = "alertOxygen", name = "Low oxygen", description = "Alert when oxygen drops to or below the threshold", position = 8, section = resourcesSection)
	default boolean alertOxygen()
	{
		return false;
	}

	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(keyName = "oxygenThreshold", name = "Oxygen threshold", description = "Oxygen threshold", position = 9, section = resourcesSection)
	default int oxygenThreshold()
	{
		return 20;
	}

	@ConfigItem(keyName = "alertSpecial", name = "Special attack restored", description = "Alert when special attack energy rises to or above the threshold", position = 10, section = resourcesSection)
	default boolean alertSpecial()
	{
		return false;
	}

	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(keyName = "specialThreshold", name = "Special attack threshold", description = "Special attack threshold", position = 11, section = resourcesSection)
	default int specialThreshold()
	{
		return 100;
	}

	// endregion

	// region Damage taken

	@ConfigItem(
		keyName = "alertDamage",
		name = "Damage taken",
		description = "Send a signal when you take damage of at least the minimum",
		position = 0,
		section = damageSection
	)
	default boolean alertDamage()
	{
		return false;
	}

	@Range(min = 1)
	@ConfigItem(
		keyName = "damageThreshold",
		name = "Minimum damage",
		description = "Smallest single hit that sends a signal. Hits are never added together",
		position = 1,
		section = damageSection
	)
	default int damageThreshold()
	{
		return 1;
	}

	@ConfigItem(
		keyName = "damageOverTime",
		name = "Count damage over time",
		description = "Count poison and venom damage",
		position = 2,
		section = damageSection
	)
	default boolean damageOverTime()
	{
		return true;
	}

	@Range(min = 0)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "damageCooldown",
		name = "Cooldown",
		description = "Minimum time between damage signals. 0 sends one for every qualifying hit",
		position = 3,
		section = damageSection
	)
	default int damageCooldown()
	{
		return 0;
	}

	// endregion

	// region Logout warnings

	@ConfigItem(
		keyName = "warnIdleLogout",
		name = "Idle logout warning",
		description = "Warn shortly before the game logs you out for idling",
		position = 0,
		section = logoutSection
	)
	default boolean warnIdleLogout()
	{
		return false;
	}

	@ConfigItem(
		keyName = "warnSixHour",
		name = "Six hour logout warning",
		description = "Warn shortly before the six hour session limit",
		position = 1,
		section = logoutSection
	)
	default boolean warnSixHour()
	{
		return false;
	}

	// endregion
}

package com.activitynotifier;

import com.activitynotifier.damage.DamageAlertTracker;
import com.activitynotifier.damage.DamageSettings;
import com.activitynotifier.detection.Activity;
import com.activitynotifier.detection.ActivityTracker;
import com.activitynotifier.detection.AnimationCatalog;
import com.activitynotifier.detection.CustomAnimations;
import com.activitynotifier.detection.Detector;
import com.activitynotifier.detection.WeaponSpeed;
import com.activitynotifier.detection.XpGainTracker;
import com.activitynotifier.resources.ResourceAlertTracker;
import com.activitynotifier.resources.ResourceType;
import com.activitynotifier.signals.SignalDispatcher;
import com.activitynotifier.ui.ActivityNotifierPanel;
import com.activitynotifier.warnings.LogoutWarningTracker;
import com.google.inject.Provides;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Activity Notifier",
	description = "Signals when you stop and resume activity, in a format the Watchdog plugin can react to",
	tags = {"idle", "afk", "activity", "notification", "notifier", "watchdog", "skilling", "damage", "hit", "animation",
		"inactive", "inactivity", "reminder", "alert", "warning", "low", "hp", "hitpoints", "prayer", "run", "energy", "spec",
		"logout", "combat"}
)
public class ActivityNotifierPlugin extends Plugin
{
	static final String CLEARED_PLUGIN_STOPPED = "Plugin stopped";
	static final String CLEARED_PAUSED = "Detection paused";

	private static final String ATTACK_ACTION = "Attack";
	private static final String SHOW_SIDE_PANEL_KEY = "showSidePanel";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ActivityNotifierConfig config;

	@Inject
	private SignalDispatcher dispatcher;

	@Inject
	private KeyManager keyManager;

	@Inject
	private WeaponSpeed weaponSpeed;

	@Inject
	private ClientToolbar clientToolbar;

	private final Clock clock = Clock.systemUTC();
	private final XpGainTracker xpGainTracker = new XpGainTracker();
	private final LogoutWarningTracker logoutWarnings = new LogoutWarningTracker();

	/**
	 * Set when a new game session starts (login, hop, reconnect), so the next LOGGED_IN starts the
	 * six-hour timer. Matches core Idle Notifier. Client thread only.
	 */
	private boolean sessionStarting;

	private final HotkeyListener pauseHotkeyListener = new HotkeyListener(() -> config.pauseHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			// Fired on the AWT thread; tracker state belongs to the client thread
			clientThread.invoke(ActivityNotifierPlugin.this::togglePause);
		}
	};

	private ActivityTracker activityTracker;

	/**
	 * True once the player is in the world after login/hop/loading (FR-008). Client thread only.
	 */
	private boolean ready;
	private boolean paused;

	/**
	 * The local player's location on the previous tick, for the movement detector. Client thread only.
	 */
	private WorldPoint lastLocation;

	private Map<ResourceType, ResourceAlertTracker> resourceTrackers;
	private DamageAlertTracker damageTracker;

	/**
	 * The player's "Custom animation IDs", parsed when the setting's text changes. Client thread only.
	 */
	private CustomAnimations customAnimations;

	/**
	 * The last animation sent to the side panel, so it is only updated when a new one starts. Client thread
	 * only. Not reset on logout or hop, so the panel keeps showing it.
	 */
	private int lastAnimationShown;

	private ActivityNotifierPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp() throws Exception
	{
		panel = new ActivityNotifierPanel(configManager, config);
		navButton = NavigationButton.builder()
			.tooltip("Activity Notifier")
			.icon(ImageUtil.loadImageResource(getClass(), "panel_icon.png"))
			.priority(10)
			.panel(panel)
			.build();
		if (config.showSidePanel())
		{
			clientToolbar.addNavigation(navButton);
		}

		activityTracker = new ActivityTracker(this::effectiveDelayMs, d -> d.isEnabled(configManager), this::reminderInterval);
		resourceTrackers = new EnumMap<>(ResourceType.class);
		for (ResourceType type : ResourceType.values())
		{
			resourceTrackers.put(type, new ResourceAlertTracker(type));
		}
		damageTracker = new DamageAlertTracker();
		customAnimations = new CustomAnimations();
		lastAnimationShown = -1;
		weaponSpeed.reset();
		xpGainTracker.reset();
		logoutWarnings.reset();
		sessionStarting = false;
		ready = false;
		paused = false;
		lastLocation = null;
		keyManager.registerKeyListener(pauseHotkeyListener);
		log.debug("Activity Notifier started");
	}

	@Override
	protected void shutDown() throws Exception
	{
		keyManager.unregisterKeyListener(pauseHotkeyListener);
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;

		// Clear any outstanding Inactive or resource alert so dependent Watchdog effects are removed (FR-012)
		final ActivityTracker tracker = activityTracker;
		final Map<ResourceType, ResourceAlertTracker> resources = resourceTrackers;
		clientThread.invoke(() ->
		{
			tracker.clear(CLEARED_PLUGIN_STOPPED).ifPresent(dispatcher::dispatch);
			clearResources(resources, CLEARED_PLUGIN_STOPPED);
		});
		log.debug("Activity Notifier stopped");
	}

	@Provides
	ActivityNotifierConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ActivityNotifierConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ActivityNotifierConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if (SHOW_SIDE_PANEL_KEY.equals(event.getKey()))
		{
			// applies immediately, without restarting the plugin (FR-029)
			if (config.showSidePanel())
			{
				clientToolbar.addNavigation(navButton);
			}
			else
			{
				clientToolbar.removeNavigation(navButton);
			}
			return;
		}

		refreshPanel();
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		// every setting may have changed (FR-022)
		refreshPanel();
	}

	private void refreshPanel()
	{
		final ActivityNotifierPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::refresh);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		trackSession(event.getGameState());

		switch (event.getGameState())
		{
			case LOGGED_IN:
				// becomes ready on the next game tick, once the player is in the world
				break;
			case LOADING:
				// keep state across loading screens so an outstanding Inactive is never dropped
				ready = false;
				lastLocation = null;
				activityTracker.suspend(clock.instant());
				break;
			default:
				// logout, hop, connection lost: discard state silently
				ready = false;
				lastLocation = null;
				activityTracker.reset();
				xpGainTracker.reset();
				resourceTrackers.values().forEach(ResourceAlertTracker::reset);
				damageTracker.discardPending();
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Instant now = clock.instant();
		if (!ready)
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}
			ready = true;
			// covers starting the plugin mid-session, when no ItemContainerChanged has been seen
			weaponSpeed.update(client.getItemContainer(InventoryID.WORN));
			if (!xpGainTracker.isSeeded())
			{
				seedXp();
			}
			activityTracker.resume(now);
		}

		// warnings matter most while AFK, so they are not affected by the pause hotkey
		checkLogoutWarnings(now);

		if (paused)
		{
			return;
		}

		Player local = client.getLocalPlayer();
		if (local != null)
		{
			// Long animations and interactions don't re-fire events, so re-observe them each tick
			int animation = local.getAnimation();
			observeAnimation(animation);
			Actor target = local.getInteracting();
			if (target != null)
			{
				observeInteraction(target);
			}
			observeMovement(local.getWorldLocation(), animation);
		}

		activityTracker.evaluate(now).ifPresent(dispatcher::dispatch);

		for (ResourceType type : ResourceType.values())
		{
			sampleResource(type);
		}

		flushDamage(now);
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() != client.getLocalPlayer())
		{
			return;
		}
		int animation = event.getActor().getAnimation();
		// shown even while paused or with detectors off, so players can look up IDs (003 FR-013)
		showLastAnimation(animation);
		observeAnimation(animation);
	}

	/**
	 * Sends a newly started animation to the side panel, on the EDT. No animation (-1) never replaces the
	 * one shown.
	 */
	private void showLastAnimation(int animation)
	{
		if (animation == -1 || animation == lastAnimationShown)
		{
			return;
		}
		lastAnimationShown = animation;

		final ActivityNotifierPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.setLastAnimation(animation));
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (event.getSource() != client.getLocalPlayer() || event.getTarget() == null)
		{
			return;
		}
		observeInteraction(event.getTarget());
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		xpGainTracker.onXp(event.getSkill(), event.getXp(), config.xpThreshold())
			.ifPresent(skill -> observe(Detector.XP_GAIN, skill.getName()));

		// sample HP and prayer as soon as they change, not only on the next tick (research R8)
		if (ready && !paused)
		{
			if (event.getSkill() == Skill.HITPOINTS)
			{
				sampleResource(ResourceType.HITPOINTS);
			}
			else if (event.getSkill() == Skill.PRAYER)
			{
				sampleResource(ResourceType.PRAYER);
			}
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Hitsplat hitsplat = event.getHitsplat();
		if (event.getActor() == client.getLocalPlayer())
		{
			// damage taken, which is not activity. Sent on the next tick, once hitpoints include it
			if (config.alertDamage() && ready && !paused)
			{
				damageTracker.record(hitsplat.getHitsplatType(), hitsplat.getAmount());
			}
			return;
		}

		if (hitsplat.isMine())
		{
			observe(Detector.COMBAT, Detector.COMBAT.getDisplayName());
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.WORN)
		{
			weaponSpeed.update(event.getItemContainer());
		}
	}

	private void trackSession(GameState state)
	{
		switch (state)
		{
			case LOGIN_SCREEN:
				sessionStarting = false;
				logoutWarnings.reset();
				break;
			case LOGGING_IN:
			case HOPPING:
			case CONNECTION_LOST:
				// the game's six-hour timer restarts with each new world session, as core assumes
				sessionStarting = true;
				break;
			case LOGGED_IN:
				if (sessionStarting)
				{
					sessionStarting = false;
					logoutWarnings.onLogin(clock.instant());
				}
				break;
			default:
				break;
		}
	}

	private void checkLogoutWarnings(Instant now)
	{
		if (config.warnIdleLogout())
		{
			int idleTicks = Math.min(client.getMouseIdleTicks(), client.getKeyboardIdleTicks());
			logoutWarnings.checkIdle(idleTicks, client.getIdleTimeout()).ifPresent(dispatcher::dispatch);
		}
		if (config.warnSixHour())
		{
			logoutWarnings.checkSession(now).ifPresent(dispatcher::dispatch);
		}
	}

	private void sampleResource(ResourceType type)
	{
		ResourceAlertTracker tracker = resourceTrackers.get(type);
		int threshold = type.threshold(configManager);
		if (!type.isEnabled(configManager) || !resourceApplies(type, threshold))
		{
			// an alert turned off (or no longer applicable) while triggered sends its recovered signal
			tracker.clear(ResourceAlertTracker.CLEARED_ALERT_OFF).ifPresent(dispatcher::dispatch);
			return;
		}
		tracker.sample(readResource(type), threshold).ifPresent(dispatcher::dispatch);
	}

	/**
	 * Core Idle Notifier's guard: a level at or below the threshold would leave the alert permanently on.
	 */
	private boolean resourceApplies(ResourceType type, int threshold)
	{
		switch (type)
		{
			case HITPOINTS:
				return client.getRealSkillLevel(Skill.HITPOINTS) > threshold;
			case PRAYER:
				return client.getRealSkillLevel(Skill.PRAYER) > threshold;
			default:
				return true;
		}
	}

	/**
	 * Reads a resource's current value in its unit (research R8).
	 */
	private int readResource(ResourceType type)
	{
		switch (type)
		{
			case HITPOINTS:
				// Nightmare Zone absorption counts as hitpoints, as in core
				return client.getBoostedSkillLevel(Skill.HITPOINTS) + client.getVarbitValue(VarbitID.NZONE_ABSORB_POTION_EFFECTS);
			case PRAYER:
				return client.getBoostedSkillLevel(Skill.PRAYER);
			case RUN_ENERGY_LOW:
			case RUN_ENERGY_HIGH:
				// energy is in hundredths of a percent
				return client.getEnergy() / 100;
			case OXYGEN:
				// tenths of a percent
				return client.getVarbitValue(VarbitID.FOSSIL_UNDERWATER_OXYGEN) / 10;
			case SPECIAL_ATTACK:
				// tenths of a percent
				return client.getVarpValue(VarPlayerID.SA_ENERGY) / 10;
			default:
				throw new IllegalArgumentException(type.toString());
		}
	}

	private void flushDamage(Instant now)
	{
		if (!config.alertDamage())
		{
			// a hit recorded just before the alert was turned off is never sent
			damageTracker.discardPending();
			return;
		}
		damageTracker.flush(damageSettings(), client.getBoostedSkillLevel(Skill.HITPOINTS), now)
			.forEach(dispatcher::dispatch);
	}

	private DamageSettings damageSettings()
	{
		return new DamageSettings(config.damageThreshold(), config.damageOverTime(),
			Duration.ofSeconds(Math.max(0, config.damageCooldown())));
	}

	private void clearResources(Map<ResourceType, ResourceAlertTracker> trackers, String detail)
	{
		for (ResourceAlertTracker tracker : trackers.values())
		{
			tracker.clear(detail).ifPresent(dispatcher::dispatch);
		}
	}

	private void seedXp()
	{
		Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			xp.put(skill, client.getSkillExperience(skill));
		}
		xpGainTracker.seed(xp);
	}

	private void observeAnimation(int animation)
	{
		if (AnimationCatalog.isHelmAnimation(animation))
		{
			// steering a ship counts only towards Sailing (analysis decision A1)
			observe(Detector.SAILING, Detector.SAILING.getDisplayName());
			return;
		}

		String name = AnimationCatalog.activityFor(animation);
		if (name == null)
		{
			// checked last, so a listed built-in or helm animation keeps its built-in meaning (003 FR-004)
			if (customAnimations.ids(config.customAnimationIds()).contains(animation))
			{
				observe(Detector.ANIMATION, Detector.ANIMATION.getDisplayName());
			}
			return;
		}

		// specific first, so a resume from Inactive is named after it (FR-010a)
		Detector specific = Detector.forCatalogActivity(name);
		if (specific != null)
		{
			observe(specific, specific.getDisplayName());
		}
		observe(Detector.ANIMATION, name);
	}

	private void observeInteraction(Actor target)
	{
		if (isAttackable(target))
		{
			observe(Detector.COMBAT, Detector.COMBAT.getDisplayName());
			observe(Detector.INTERACTION, Detector.COMBAT.getDisplayName());
		}
		else
		{
			observe(Detector.INTERACTION, Detector.INTERACTION.getDisplayName());
		}
	}

	private void observeMovement(WorldPoint location, int animation)
	{
		WorldPoint previous = lastLocation;
		lastLocation = location;
		// ship-helm animations are not movement (analysis decision A1)
		if (previous != null && !previous.equals(location) && !AnimationCatalog.isHelmAnimation(animation))
		{
			observe(Detector.MOVEMENT, Detector.MOVEMENT.getDisplayName());
		}
	}

	private void observe(Detector detector, String activityName)
	{
		if (!ready || paused)
		{
			return;
		}
		activityTracker.observe(detector, new Activity(activityName, detector), clock.instant())
			.ifPresent(dispatcher::dispatch);
	}

	private static boolean isAttackable(Actor target)
	{
		if (!(target instanceof NPC))
		{
			return false;
		}

		NPC npc = (NPC) target;
		NPCComposition composition = npc.getTransformedComposition();
		if (composition == null)
		{
			composition = npc.getComposition();
		}
		if (composition == null)
		{
			return false;
		}

		for (String action : composition.getActions())
		{
			if (ATTACK_ACTION.equals(action))
			{
				return true;
			}
		}
		return false;
	}

	private void togglePause()
	{
		paused = !paused;
		lastLocation = null;
		if (paused)
		{
			activityTracker.clear(CLEARED_PAUSED).ifPresent(dispatcher::dispatch);
			clearResources(resourceTrackers, CLEARED_PAUSED);
			// damage taken is a one-off event, so there is nothing to clear, only hits not yet sent
			damageTracker.discardPending();
		}
		else
		{
			// resuming starts fresh: no signal for what happened while paused
			activityTracker.reset();
			resourceTrackers.values().forEach(ResourceAlertTracker::reset);
		}
		dispatcher.info(paused ? "Activity detection paused." : "Activity detection resumed.");
	}

	private long effectiveDelayMs(Detector detector)
	{
		return ActivityTracker.effectiveDelayMs(detector, config.baseDelay(), detector.extraDelayMs(configManager),
			weaponSpeed.getIntervalTicks());
	}

	private Duration reminderInterval()
	{
		return config.reminderEnabled() ? Duration.ofSeconds(config.reminderInterval()) : null;
	}
}

package com.activitynotifier.damage;

import com.activitynotifier.signals.Signal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * Records hits on the local player and turns them into damage taken signals on the next game tick, so
 * the hitpoints in the signal already include the hit (specs/done/002-damage-notifier/research.md R3).
 * Each hit is judged on its own; hits are never added together (FR-004).
 */
public class DamageAlertTracker
{
	@Value
	private static class Hit
	{
		HitKind kind;
		int amount;
	}

	private final List<Hit> pending = new ArrayList<>();

	/**
	 * When the last damage taken signal was sent. Kept across logout and pause, so the cooldown is real
	 * time; only a new tracker (plugin restart) clears it.
	 */
	@Nullable
	private Instant lastSent;

	public void record(int hitsplatType, int amount)
	{
		HitKind kind = HitKind.of(hitsplatType);
		if (kind == HitKind.NONE || amount <= 0)
		{
			return;
		}
		pending.add(new Hit(kind, amount));
	}

	public List<Signal> flush(DamageSettings settings, int hitpoints, Instant now)
	{
		List<Signal> signals = new ArrayList<>();
		for (Hit hit : pending)
		{
			if (hit.getKind() == HitKind.DAMAGE_OVER_TIME && !settings.isCountDamageOverTime())
			{
				continue;
			}

			if (hit.getAmount() < settings.getMinimum())
			{
				continue;
			}

			// hits during the cooldown are dropped, not queued (FR-008)
			if (lastSent != null && now.isBefore(lastSent.plus(settings.getCooldown())))
			{
				continue;
			}

			signals.add(Signal.damageTaken(hit.getAmount(), settings.getMinimum(), hitpoints));
			lastSent = now;
		}
		pending.clear();
		return signals;
	}

	/**
	 * Drops hits not yet sent, e.g. on logout or pause. Does not reset the cooldown.
	 */
	public void discardPending()
	{
		pending.clear();
	}
}

package com.activitynotifier.damage;

import java.time.Duration;
import lombok.Value;

/**
 * The damage taken settings, read from config once per flush so the tracker never touches config.
 */
@Value
public class DamageSettings
{
	/**
	 * Smallest single hit that sends a signal (inclusive).
	 */
	int minimum;

	/**
	 * Whether poison and venom hits count.
	 */
	boolean countDamageOverTime;

	/**
	 * Minimum time between signals. {@link Duration#ZERO} sends one for every qualifying hit.
	 */
	Duration cooldown;
}

package com.activitynotifier.damage;

import net.runelite.api.HitsplatID;

/**
 * What a hitsplat on the local player counts as for the damage taken alert
 * (specs/done/002-damage-notifier/research.md R2). gameval has no hitsplat class, so
 * {@link HitsplatID} is the constant source.
 */
public enum HitKind
{
	/**
	 * A hit that takes hitpoints.
	 */
	DIRECT,
	/**
	 * Poison and venom, which can be excluded in settings.
	 */
	DAMAGE_OVER_TIME,
	/**
	 * Never counts: 0 hits, healing, other damage over time, drains and NPC shield/armour bars.
	 * Unknown types fall here too, so new game splats stay quiet.
	 */
	NONE;

	public static HitKind of(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_MAX_ME:
			// the hit is already known to be on the local player, so any tint is damage to them
			case HitsplatID.DAMAGE_OTHER:
				return DIRECT;
			case HitsplatID.POISON:
			case HitsplatID.VENOM:
				return DAMAGE_OVER_TIME;
			default:
				return NONE;
		}
	}
}

package com.activitynotifier.detection;

import lombok.Value;

/**
 * What the player was doing, as named in signals (FR-010a), and which detector saw it.
 */
@Value
public class Activity
{
	String name;
	Detector detector;
}

package com.activitynotifier.detection;

import com.activitynotifier.signals.Signal;
import java.time.Duration;
import java.time.Instant;
import java.util.EnumMap;
import java.util.Map;
import java.util.Optional;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Constants;

/**
 * Pure Active/Inactive state machine (data-model.md). Has no client dependency; all times are passed in.
 * Must only be used from one thread (the client thread).
 */
@Slf4j
public class ActivityTracker
{
	/**
	 * Base delay + per-detector extra delay (+ weapon interval for combat), in milliseconds.
	 */
	@FunctionalInterface
	public interface DelayProvider
	{
		long effectiveDelayMs(Detector detector);
	}

	@FunctionalInterface
	public interface EnabledProvider
	{
		boolean isEnabled(Detector detector);
	}

	/**
	 * Reminder interval, or null when reminders are disabled.
	 */
	@FunctionalInterface
	public interface ReminderProvider
	{
		@Nullable
		Duration reminderInterval();
	}

	public enum State
	{
		NEUTRAL,
		ACTIVE,
		INACTIVE
	}

	public static final String CLEARED_DETECTION_OFF = "Detection off";

	private final DelayProvider delays;
	private final EnabledProvider enabled;
	private final ReminderProvider reminders;

	private final Map<Detector, Instant> lastSeen = new EnumMap<>(Detector.class);
	private final Map<Detector, Activity> lastActivity = new EnumMap<>(Detector.class);

	@Getter
	private State state = State.NEUTRAL;
	private Instant inactiveSince;
	private Instant lastReminderAt;
	private String inactiveActivity;
	private Instant suspendedAt;

	public ActivityTracker(DelayProvider delays, EnabledProvider enabled, ReminderProvider reminders)
	{
		this.delays = delays;
		this.enabled = enabled;
		this.reminders = reminders;
	}

	/**
	 * The effective delay for a detector: base + extra, plus the weapon attack interval for combat (FR-005).
	 */
	public static long effectiveDelayMs(Detector detector, long baseMs, long extraMs, int weaponIntervalTicks)
	{
		long delay = Math.max(0, baseMs) + Math.max(0, extraMs);
		if (detector == Detector.COMBAT)
		{
			delay += (long) Math.max(0, weaponIntervalTicks) * Constants.GAME_TICK_LENGTH;
		}
		return delay;
	}

	/**
	 * Records that a detector saw activity. Returns an Active signal when this resumes from Inactive.
	 */
	public Optional<Signal> observe(Detector detector, Activity activity, Instant now)
	{
		if (!enabled.isEnabled(detector))
		{
			return Optional.empty();
		}

		Instant previousSeen = lastSeen.put(detector, now);
		Activity previousActivity = lastActivity.put(detector, activity);
		if (log.isDebugEnabled() && (!activity.equals(previousActivity) || !isLive(detector, previousSeen, now)))
		{
			// only log starts and changes; detectors are re-observed every tick
			log.debug("Observed {} via {}", activity.getName(), detector);
		}

		switch (state)
		{
			case INACTIVE:
				Duration inactiveFor = Duration.between(inactiveSince, now);
				enterActive();
				log.debug("INACTIVE -> ACTIVE ({}, inactive for {})", activity.getName(), inactiveFor);
				return Optional.of(Signal.active(activity.getName(), inactiveFor));
			case NEUTRAL:
				enterActive();
				log.debug("NEUTRAL -> ACTIVE ({})", activity.getName());
				return Optional.empty();
			default:
				return Optional.empty();
		}
	}

	/**
	 * Called once per game tick. Returns an Inactive, Still inactive, or cleared signal when one is due.
	 */
	public Optional<Signal> evaluate(Instant now)
	{
		if (suspendedAt != null)
		{
			return Optional.empty();
		}

		// Turning a detector off forgets it, so a settings change can never cause Inactive (analysis I1)
		lastSeen.keySet().removeIf(d -> !enabled.isEnabled(d));
		lastActivity.keySet().retainAll(lastSeen.keySet());

		if (!anyDetectorEnabled())
		{
			State before = state;
			reset();
			if (before != State.NEUTRAL)
			{
				log.debug("{} -> NEUTRAL (no detectors enabled)", before);
			}
			return before == State.INACTIVE
				? Optional.of(Signal.cleared(CLEARED_DETECTION_OFF))
				: Optional.empty();
		}

		if (state == State.ACTIVE)
		{
			return evaluateActive(now);
		}

		if (state == State.INACTIVE)
		{
			return evaluateReminder(now);
		}

		return Optional.empty();
	}

	private Optional<Signal> evaluateActive(Instant now)
	{
		if (lastSeen.isEmpty())
		{
			// Only seen by detectors that are now off: wait for an enabled detector to be seen and expire
			return Optional.empty();
		}

		Detector mostRecentlyExpired = null;
		Instant latestExpiry = null;
		for (Map.Entry<Detector, Instant> entry : lastSeen.entrySet())
		{
			Instant expiry = expiry(entry.getKey(), entry.getValue());
			if (now.isBefore(expiry))
			{
				// still live
				return Optional.empty();
			}
			// on a tie the later detector wins: SPECIFIC detectors come after GENERAL ones, and their name
			// is the more specific one (FR-010a)
			if (latestExpiry == null || !expiry.isBefore(latestExpiry))
			{
				latestExpiry = expiry;
				mostRecentlyExpired = entry.getKey();
			}
		}

		state = State.INACTIVE;
		inactiveSince = now;
		lastReminderAt = now;
		inactiveActivity = lastActivity.get(mostRecentlyExpired).getName();
		log.debug("ACTIVE -> INACTIVE ({} via {})", inactiveActivity, mostRecentlyExpired);
		return Optional.of(Signal.inactive(inactiveActivity));
	}

	private Instant expiry(Detector detector, Instant seen)
	{
		return seen.plusMillis(Math.max(0, delays.effectiveDelayMs(detector)));
	}

	private boolean isLive(Detector detector, @Nullable Instant seen, Instant now)
	{
		return seen != null && now.isBefore(expiry(detector, seen));
	}

	private Optional<Signal> evaluateReminder(Instant now)
	{
		Duration interval = reminders.reminderInterval();
		if (interval == null || interval.isZero() || interval.isNegative())
		{
			return Optional.empty();
		}

		if (Duration.between(lastReminderAt, now).compareTo(interval) >= 0)
		{
			lastReminderAt = now;
			return Optional.of(Signal.stillInactive(inactiveActivity, Duration.between(inactiveSince, now)));
		}
		return Optional.empty();
	}

	/**
	 * Returns to neutral. Emits an Active signal with the given detail if an Inactive signal is outstanding
	 * (FR-012: pause, plugin shutdown).
	 */
	public Optional<Signal> clear(String detail)
	{
		State before = state;
		reset();
		if (before != State.NEUTRAL)
		{
			log.debug("{} -> NEUTRAL ({})", before, detail);
		}
		return before == State.INACTIVE ? Optional.of(Signal.cleared(detail)) : Optional.empty();
	}

	/**
	 * Discards all state silently (logout, world hop).
	 */
	public void reset()
	{
		state = State.NEUTRAL;
		lastSeen.clear();
		lastActivity.clear();
		inactiveSince = null;
		lastReminderAt = null;
		inactiveActivity = null;
		suspendedAt = null;
	}

	/**
	 * Stops evaluation without losing state (loading screens).
	 */
	public void suspend(Instant now)
	{
		if (suspendedAt == null)
		{
			suspendedAt = now;
		}
	}

	/**
	 * Resumes after {@link #suspend}, shifting all timestamps by the suspended time so no detector
	 * expires because of the loading screen.
	 */
	public void resume(Instant now)
	{
		if (suspendedAt == null)
		{
			return;
		}

		Duration suspended = Duration.between(suspendedAt, now);
		suspendedAt = null;
		if (suspended.isNegative() || suspended.isZero())
		{
			return;
		}

		lastSeen.replaceAll((d, t) -> t.plus(suspended));
		if (inactiveSince != null)
		{
			inactiveSince = inactiveSince.plus(suspended);
		}
		if (lastReminderAt != null)
		{
			lastReminderAt = lastReminderAt.plus(suspended);
		}
	}

	private void enterActive()
	{
		state = State.ACTIVE;
		inactiveSince = null;
		lastReminderAt = null;
		inactiveActivity = null;
	}

	private boolean anyDetectorEnabled()
	{
		for (Detector detector : Detector.values())
		{
			if (enabled.isEnabled(detector))
			{
				return true;
			}
		}
		return false;
	}
}

