package com.activitynotifier.detection;

import com.google.common.collect.ImmutableSet;
import java.util.Set;
import javax.annotation.Nullable;

/**
 * The player's own animation IDs from the "Custom animation IDs" setting (see
 * specs/done/003-custom-animation-ids/contracts/config.md). Listed animations count for the Animation detector,
 * after ship-helm and built-in animations.
 * <p>
 * An instance caches the parsed set until the setting's text changes. Client thread only.
 */
public final class CustomAnimations
{
	public static final String NOT_COUNTED = "Not counted";

	private String lastText = "";
	private Set<Integer> lastIds = ImmutableSet.of();

	/**
	 * Parses comma-separated animation IDs. Spaces around entries are ignored, empty entries are skipped, and
	 * any entry that isn't a whole number of 0 or more is ignored without affecting the others. Never throws.
	 */
	public static Set<Integer> parse(@Nullable String text)
	{
		if (text == null || text.trim().isEmpty())
		{
			return ImmutableSet.of();
		}

		ImmutableSet.Builder<Integer> ids = ImmutableSet.builder();
		for (String entry : text.split(","))
		{
			String trimmed = entry.trim();
			if (trimmed.isEmpty())
			{
				continue;
			}

			try
			{
				int id = Integer.parseInt(trimmed);
				// -1 means no animation, so negatives never count
				if (id >= 0)
				{
					ids.add(id);
				}
			}
			catch (NumberFormatException e)
			{
				// a typo; skip it and keep the rest of the list
			}
		}
		return ids.build();
	}

	/**
	 * How the plugin counts an animation, for the side panel. Checked in the same order as the plugin:
	 * ship-helm (Sailing), then built-in (its activity name), then listed ("Animation", the name its signals
	 * use).
	 */
	public static String countedAs(int animation, Set<Integer> custom)
	{
		if (AnimationCatalog.isHelmAnimation(animation))
		{
			return Detector.SAILING.getDisplayName();
		}

		String name = AnimationCatalog.activityFor(animation);
		if (name != null)
		{
			return name;
		}
		return custom.contains(animation) ? Detector.ANIMATION.getDisplayName() : NOT_COUNTED;
	}

	/**
	 * The IDs in the setting's current text, re-parsed only when the text has changed since the last call.
	 */
	public Set<Integer> ids(@Nullable String text)
	{
		String current = text == null ? "" : text;
		if (!current.equals(lastText))
		{
			lastText = current;
			lastIds = parse(current);
		}
		return lastIds;
	}
}

package com.activitynotifier.detection;

import com.activitynotifier.ActivityNotifierConfig;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.ConfigManager;

/**
 * A source of activity that can be toggled individually. Key names must match
 * {@link ActivityNotifierConfig} (contracts/config.md).
 */
@Getter
@RequiredArgsConstructor
public enum Detector
{
	ANIMATION(Group.GENERAL, "Animation", "detectAnimation", "delayAnimation", true, 0),
	INTERACTION(Group.GENERAL, "Interaction", "detectInteraction", "delayInteraction", true, 0),
	MOVEMENT(Group.GENERAL, "Movement", "detectMovement", "delayMovement", false, 2000),
	XP_GAIN(Group.GENERAL, "XP gain", "detectXpGain", "delayXpGain", true, 3000),

	COOKING(Group.SPECIFIC, "Cooking", "detectCooking", "delayCooking", false, 0),
	CRAFTING(Group.SPECIFIC, "Crafting", "detectCrafting", "delayCrafting", false, 0),
	FISHING(Group.SPECIFIC, "Fishing", "detectFishing", "delayFishing", false, 0),
	FIREMAKING(Group.SPECIFIC, "Firemaking", "detectFiremaking", "delayFiremaking", false, 0),
	FLETCHING(Group.SPECIFIC, "Fletching", "detectFletching", "delayFletching", false, 0),
	HERBLORE(Group.SPECIFIC, "Herblore", "detectHerblore", "delayHerblore", false, 0),
	MINING(Group.SPECIFIC, "Mining", "detectMining", "delayMining", false, 0),
	WOODCUTTING(Group.SPECIFIC, "Woodcutting", "detectWoodcutting", "delayWoodcutting", false, 0),
	SMITHING(Group.SPECIFIC, "Smithing", "detectSmithing", "delaySmithing", false, 0),
	SAILING(Group.SPECIFIC, "Sailing", "detectSailing", "delaySailing", false, 0),
	COMBAT(Group.SPECIFIC, "Combat", "detectCombat", "delayCombat", false, 0),
	MAGIC_SKILLING(Group.SPECIFIC, "Magic skilling", "detectMagicSkilling", "delayMagicSkilling", false, 0);

	public enum Group
	{
		GENERAL,
		SPECIFIC
	}

	private final Group group;
	private final String displayName;
	private final String enabledKey;
	private final String delayKey;
	private final boolean defaultEnabled;
	private final int defaultDelayMs;

	/**
	 * The SPECIFIC detector that watches an {@link AnimationCatalog} activity, or null if none does.
	 */
	@Nullable
	public static Detector forCatalogActivity(String activity)
	{
		switch (activity)
		{
			case AnimationCatalog.COOKING:
				return COOKING;
			case AnimationCatalog.CRAFTING:
				return CRAFTING;
			case AnimationCatalog.FISHING:
				return FISHING;
			case AnimationCatalog.FIREMAKING:
				return FIREMAKING;
			case AnimationCatalog.FLETCHING:
				return FLETCHING;
			case AnimationCatalog.HERBLORE:
				return HERBLORE;
			case AnimationCatalog.MINING:
				return MINING;
			case AnimationCatalog.WOODCUTTING:
				return WOODCUTTING;
			case AnimationCatalog.SMITHING:
				return SMITHING;
			case AnimationCatalog.SAILING:
				return SAILING;
			case AnimationCatalog.MAGIC:
				return MAGIC_SKILLING;
			default:
				return null;
		}
	}

	/**
	 * Not yet validated in-game; labelled "(beta)" in the UI. The display name is unchanged because it is
	 * also the activity name in signals.
	 */
	public boolean isBeta()
	{
		return this == SAILING;
	}

	public boolean isEnabled(ConfigManager configManager)
	{
		Boolean value = configManager.getConfiguration(ActivityNotifierConfig.GROUP, enabledKey, Boolean.class);
		return value == null ? defaultEnabled : value;
	}

	public int extraDelayMs(ConfigManager configManager)
	{
		Integer value = configManager.getConfiguration(ActivityNotifierConfig.GROUP, delayKey, Integer.class);
		return value == null ? defaultDelayMs : Math.max(0, value);
	}
}

package com.activitynotifier.detection;

import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

/**
 * Caches the equipped weapon's attack interval in game ticks, for the combat delay (FR-005, research R7).
 * Client thread only.
 */
@Slf4j
public class WeaponSpeed
{
	/**
	 * Unarmed attack interval, also used when a weapon's speed is unknown.
	 */
	public static final int DEFAULT_TICKS = 4;

	private final ItemManager itemManager;

	@Getter
	private int intervalTicks = DEFAULT_TICKS;

	@Inject
	WeaponSpeed(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * Re-reads the weapon slot of the worn-equipment container.
	 */
	public void update(@Nullable ItemContainer worn)
	{
		int ticks = DEFAULT_TICKS;
		Item weapon = worn == null ? null : worn.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon != null && weapon.getId() > 0)
		{
			ItemStats stats = itemManager.getItemStats(weapon.getId());
			ItemEquipmentStats equipment = stats == null ? null : stats.getEquipment();
			if (equipment != null && equipment.getAspeed() > 0)
			{
				ticks = equipment.getAspeed();
			}
		}

		if (ticks != intervalTicks)
		{
			log.debug("Weapon attack interval: {} -> {} ticks", intervalTicks, ticks);
			intervalTicks = ticks;
		}
	}

	public void reset()
	{
		intervalTicks = DEFAULT_TICKS;
	}
}

package com.activitynotifier.detection;

import java.util.EnumMap;
import java.util.Map;
import java.util.Optional;
import net.runelite.api.Skill;

/**
 * Turns XP updates into XP-gain observations (FR-007, research R5). Has no client dependency.
 * Until {@link #seed} is called, updates are ignored, so the burst of StatChanged events at login
 * doesn't count as activity. Client thread only.
 */
public class XpGainTracker
{
	private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
	private boolean seeded;

	/**
	 * Caches the current XP of every skill.
	 */
	public void seed(Map<Skill, Integer> current)
	{
		xp.clear();
		xp.putAll(current);
		seeded = true;
	}

	/**
	 * Records a skill's XP. Returns the skill when it gained at least {@code threshold} XP since the last update.
	 */
	public Optional<Skill> onXp(Skill skill, int value, int threshold)
	{
		if (!seeded)
		{
			return Optional.empty();
		}

		Integer previous = xp.put(skill, value);
		if (previous == null)
		{
			return Optional.empty();
		}

		int gained = value - previous;
		return gained > 0 && gained >= threshold ? Optional.of(skill) : Optional.empty();
	}

	/**
	 * Forgets the cache (logout, hop); updates are ignored until the next {@link #seed}.
	 */
	public void reset()
	{
		xp.clear();
		seeded = false;
	}

	public boolean isSeeded()
	{
		return seeded;
	}
}

package com.activitynotifier.resources;

import com.activitynotifier.signals.Signal;
import java.util.Optional;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * Hysteresis state machine for one resource (data-model.md, FR-023 to FR-025): one alert per crossing
 * and one recovered signal when the value crosses back. Has no client dependency. Client thread only.
 */
@Slf4j
public class ResourceAlertTracker
{
	public enum State
	{
		UNKNOWN,
		NORMAL,
		ALERTED
	}

	public static final String CLEARED_ALERT_OFF = "Alert off";

	@Getter
	private final ResourceType type;

	@Getter
	private State state = State.UNKNOWN;

	public ResourceAlertTracker(ResourceType type)
	{
		this.type = type;
	}

	/**
	 * Records the current value. The first sample is silent, so logging in below a threshold never alerts.
	 */
	public Optional<Signal> sample(int value, int threshold)
	{
		boolean alerting = type.isAlerting(value, threshold);
		switch (state)
		{
			case UNKNOWN:
				state = alerting ? State.ALERTED : State.NORMAL;
				log.debug("{}: UNKNOWN -> {} (value {}, threshold {})", type, state, value, threshold);
				return Optional.empty();
			case NORMAL:
				if (alerting)
				{
					state = State.ALERTED;
					log.debug("{}: NORMAL -> ALERTED (value {}, threshold {})", type, value, threshold);
					return Optional.of(Signal.resourceAlert(type.getAlertKeyword(), type.getDisplayName(),
						type.format(value), type.format(threshold)));
				}
				return Optional.empty();
			case ALERTED:
				if (!alerting)
				{
					state = State.NORMAL;
					log.debug("{}: ALERTED -> NORMAL (value {}, threshold {})", type, value, threshold);
					return Optional.of(Signal.resourceRecovered(type.getRecoveredKeyword(), type.getDisplayName(),
						type.format(value)));
				}
				return Optional.empty();
			default:
				return Optional.empty();
		}
	}

	/**
	 * Returns to UNKNOWN. Emits a recovered signal with the given detail if an alert is outstanding
	 * (alert turned off, pause, plugin shutdown).
	 */
	public Optional<Signal> clear(String detail)
	{
		State before = state;
		state = State.UNKNOWN;
		if (before != State.ALERTED)
		{
			return Optional.empty();
		}
		log.debug("{}: ALERTED -> UNKNOWN ({})", type, detail);
		return Optional.of(Signal.resourceCleared(type.getRecoveredKeyword(), type.getDisplayName(), detail));
	}

	/**
	 * Discards state silently (logout, world hop).
	 */
	public void reset()
	{
		state = State.UNKNOWN;
	}
}

package com.activitynotifier.resources;

import com.activitynotifier.ActivityNotifierConfig;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.ConfigManager;

/**
 * Resources that can raise threshold alerts (FR-023). Keywords are part of the public signal contract
 * (contracts/signals.md) and key names must match {@link ActivityNotifierConfig} (contracts/config.md).
 */
@Getter
@RequiredArgsConstructor
public enum ResourceType
{
	HITPOINTS(Direction.LOW, "Hitpoints", Unit.POINTS, "alertHitpoints", "hitpointsThreshold", 10,
		"Low hitpoints", "Hitpoints recovered"),
	PRAYER(Direction.LOW, "Prayer", Unit.POINTS, "alertPrayer", "prayerThreshold", 10,
		"Low prayer", "Prayer recovered"),
	RUN_ENERGY_LOW(Direction.LOW, "Run energy", Unit.PERCENT, "alertLowEnergy", "lowEnergyThreshold", 10,
		"Low run energy", "Run energy recovered"),
	RUN_ENERGY_HIGH(Direction.HIGH, "Run energy", Unit.PERCENT, "alertHighEnergy", "highEnergyThreshold", 90,
		"Run energy restored", "Run energy used"),
	OXYGEN(Direction.LOW, "Oxygen", Unit.PERCENT, "alertOxygen", "oxygenThreshold", 20,
		"Low oxygen", "Oxygen recovered"),
	SPECIAL_ATTACK(Direction.HIGH, "Special attack", Unit.PERCENT, "alertSpecial", "specialThreshold", 100,
		"Special attack restored", "Special attack used");

	public enum Direction
	{
		/**
		 * Alert when the value drops to or below the threshold.
		 */
		LOW,
		/**
		 * Alert when the value rises to or above the threshold ("restored").
		 */
		HIGH
	}

	public enum Unit
	{
		POINTS,
		PERCENT
	}

	private final Direction direction;
	private final String displayName;
	private final Unit unit;
	private final String enabledKey;
	private final String thresholdKey;
	private final int defaultThreshold;
	private final String alertKeyword;
	private final String recoveredKeyword;

	/**
	 * All resource alerts are off by default (FR-026).
	 */
	public boolean isEnabled(ConfigManager configManager)
	{
		Boolean value = configManager.getConfiguration(ActivityNotifierConfig.GROUP, enabledKey, Boolean.class);
		return value != null && value;
	}

	public int threshold(ConfigManager configManager)
	{
		Integer value = configManager.getConfiguration(ActivityNotifierConfig.GROUP, thresholdKey, Integer.class);
		return value == null ? defaultThreshold : Math.max(0, value);
	}

	/**
	 * Whether a value is on the alert side of the threshold.
	 */
	public boolean isAlerting(int value, int threshold)
	{
		return direction == Direction.LOW ? value <= threshold : value >= threshold;
	}

	/**
	 * Formats a value with its unit, e.g. {@code 9} or {@code 85%}.
	 */
	public String format(int value)
	{
		return unit == Unit.PERCENT ? value + "%" : Integer.toString(value);
	}
}

package com.activitynotifier.signals;

import java.time.Duration;
import javax.annotation.Nullable;
import lombok.Builder;
import lombok.Value;

/**
 * A message emitted on a state transition.
 */
@Value
@Builder
public class Signal
{
	SignalType type;

	/**
	 * Keyword that follows the "Activity Notifier: " prefix.
	 */
	String keyword;

	@Nullable
	String activity;

	@Nullable
	String resource;

	/**
	 * Current resource value, already formatted with its unit (e.g. "9" or "85%").
	 */
	@Nullable
	String value;

	/**
	 * Resource threshold, already formatted with its unit.
	 */
	@Nullable
	String threshold;

	@Nullable
	Duration duration;

	/**
	 * Damage of the hit that triggered a damage taken signal.
	 */
	@Nullable
	String damage;

	/**
	 * The player's hitpoints when a damage taken signal is sent.
	 */
	@Nullable
	String hitpoints;

	/**
	 * When set, used as the detail instead of the user's template (e.g. cleared signals).
	 */
	@Nullable
	String fixedDetail;

	public static Signal inactive(String activity)
	{
		return builder().type(SignalType.INACTIVE).keyword(SignalType.INACTIVE.getKeyword())
			.activity(activity).build();
	}

	public static Signal active(String activity, Duration inactiveFor)
	{
		return builder().type(SignalType.ACTIVE).keyword(SignalType.ACTIVE.getKeyword())
			.activity(activity).duration(inactiveFor).build();
	}

	public static Signal stillInactive(String activity, Duration inactiveFor)
	{
		return builder().type(SignalType.STILL_INACTIVE).keyword(SignalType.STILL_INACTIVE.getKeyword())
			.activity(activity).duration(inactiveFor).build();
	}

	/**
	 * An active signal sent to clear an outstanding inactive signal, e.g. when detection is paused.
	 */
	public static Signal cleared(String detail)
	{
		return builder().type(SignalType.ACTIVE).keyword(SignalType.ACTIVE.getKeyword())
			.fixedDetail(detail).build();
	}

	public static Signal idleLogout()
	{
		return builder().type(SignalType.IDLE_LOGOUT).keyword(SignalType.IDLE_LOGOUT.getKeyword()).build();
	}

	public static Signal sixHour()
	{
		return builder().type(SignalType.SIX_HOUR).keyword(SignalType.SIX_HOUR.getKeyword()).build();
	}

	public static Signal resourceAlert(String keyword, String resource, String value, String threshold)
	{
		return builder().type(SignalType.RESOURCE_ALERT).keyword(keyword)
			.resource(resource).value(value).threshold(threshold).build();
	}

	public static Signal resourceRecovered(String keyword, String resource, String value)
	{
		return builder().type(SignalType.RESOURCE_RECOVERED).keyword(keyword)
			.resource(resource).value(value).build();
	}

	public static Signal damageTaken(int damage, int minimum, int hitpoints)
	{
		return builder().type(SignalType.DAMAGE_TAKEN).keyword(SignalType.DAMAGE_TAKEN.getKeyword())
			.damage(String.valueOf(damage)).threshold(String.valueOf(minimum))
			.hitpoints(String.valueOf(hitpoints)).build();
	}

	/**
	 * A recovered signal sent to clear an outstanding resource alert, e.g. when the alert is turned off.
	 */
	public static Signal resourceCleared(String keyword, String resource, String detail)
	{
		return builder().type(SignalType.RESOURCE_RECOVERED).keyword(keyword)
			.resource(resource).fixedDetail(detail).build();
	}
}

package com.activitynotifier.signals;

import com.activitynotifier.ActivityNotifierConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

/**
 * Delivers signals to the enabled channels: a filtered chat game message and/or a RuneLite notification.
 * Watchdog matches the former with a Game Message alert (message type Spam or Any) and the latter with a
 * Notification Fired alert.
 */
@Slf4j
@Singleton
public class SignalDispatcher
{
	private final ActivityNotifierConfig config;
	private final ChatMessageManager chatMessageManager;
	private final Notifier notifier;

	@Inject
	SignalDispatcher(ActivityNotifierConfig config, ChatMessageManager chatMessageManager, Notifier notifier)
	{
		this.config = config;
		this.chatMessageManager = chatMessageManager;
		this.notifier = notifier;
	}

	public void dispatch(Signal signal)
	{
		String text = SignalFormatter.format(signal, templateFor(signal.getType()));
		log.debug("Signal: {}", text);

		if (config.chatSignals())
		{
			// SPAM is a filtered game message: hidden when the Game chat filter is "Filtered", but still
			// posted as a ChatMessage event, so Watchdog (type Spam or Any) sees it. Plain text in the
			// default filtered-message colour (contracts/signals.md)
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.SPAM)
				.runeLiteFormattedMessage(text)
				.build());
		}

		// Notifier skips this when the notification is disabled
		notifier.notify(config.notificationSignals(), text);
	}

	/**
	 * Plain chat feedback that is not a signal (e.g. pause confirmation). It deliberately does not start
	 * with the signal prefix, so Watchdog patterns for signals never match it. Sent as a normal game
	 * message, not filtered, because the player asked for it.
	 */
	public void info(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	private String templateFor(SignalType type)
	{
		switch (type)
		{
			case INACTIVE:
				return config.templateInactive();
			case ACTIVE:
				return config.templateActive();
			case STILL_INACTIVE:
				return config.templateReminder();
			case RESOURCE_ALERT:
				return config.templateResourceAlert();
			case RESOURCE_RECOVERED:
				return config.templateResourceRecovered();
			case IDLE_LOGOUT:
				return config.templateIdleLogout();
			case SIX_HOUR:
				return config.templateSixHour();
			case DAMAGE_TAKEN:
				return config.templateDamageTaken();
			default:
				return "";
		}
	}
}

package com.activitynotifier.signals;

import java.time.Duration;
import javax.annotation.Nullable;

/**
 * Renders signal text: {@code "Activity Notifier: <Keyword> - <detail>"}.
 * The head is fixed so Watchdog patterns keep working when users customise the detail template.
 */
public final class SignalFormatter
{
	public static final String PREFIX = "Activity Notifier: ";
	private static final String SEPARATOR = " - ";

	private SignalFormatter()
	{
	}

	public static String head(String keyword)
	{
		return PREFIX + keyword;
	}

	public static String format(Signal signal, @Nullable String template)
	{
		String detail = signal.getFixedDetail() != null
			? signal.getFixedDetail()
			: render(template, signal);

		String head = head(signal.getKeyword());
		return detail.isEmpty() ? head : head + SEPARATOR + detail;
	}

	static String render(@Nullable String template, Signal signal)
	{
		if (template == null)
		{
			return "";
		}

		String out = template.trim();
		out = replace(out, "{activity}", signal.getActivity());
		out = replace(out, "{duration}", signal.getDuration() == null ? null : formatDuration(signal.getDuration()));
		out = replace(out, "{resource}", signal.getResource());
		out = replace(out, "{value}", signal.getValue());
		out = replace(out, "{threshold}", signal.getThreshold());
		out = replace(out, "{damage}", signal.getDamage());
		out = replace(out, "{hitpoints}", signal.getHitpoints());
		return out;
	}

	private static String replace(String text, String token, @Nullable String value)
	{
		return value == null ? text : text.replace(token, value);
	}

	/**
	 * Formats as {@code 45s}, {@code 1m 23s} or {@code 1h 2m}.
	 */
	public static String formatDuration(Duration duration)
	{
		long totalSeconds = Math.max(0, duration.getSeconds());
		long hours = totalSeconds / 3600;
		long minutes = (totalSeconds % 3600) / 60;
		long seconds = totalSeconds % 60;

		if (hours > 0)
		{
			return hours + "h " + minutes + "m";
		}
		if (minutes > 0)
		{
			return minutes + "m " + seconds + "s";
		}
		return seconds + "s";
	}
}

package com.activitynotifier.signals;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Signal types and their fixed keywords. Keywords are part of the public contract with Watchdog
 * (see specs/done/001-activity-detection/contracts/signals.md and
 * specs/done/002-damage-notifier/contracts/signals.md); changing one is a breaking change.
 */
@Getter
@RequiredArgsConstructor
public enum SignalType
{
	INACTIVE("Inactive"),
	ACTIVE("Active"),
	STILL_INACTIVE("Still inactive"),
	/**
	 * Keyword is per resource and supplied by the {@link Signal}.
	 */
	RESOURCE_ALERT(null),
	/**
	 * Keyword is per resource and supplied by the {@link Signal}.
	 */
	RESOURCE_RECOVERED(null),
	IDLE_LOGOUT("Idle logout soon"),
	SIX_HOUR("Six hour logout soon"),
	DAMAGE_TAKEN("Damage taken");

	private final String keyword;
}

package com.activitynotifier.ui;

import com.activitynotifier.ActivityNotifierConfig;
import com.activitynotifier.detection.CustomAnimations;
import com.activitynotifier.detection.Detector;
import com.activitynotifier.resources.ResourceType;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.util.EnumMap;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.JCheckBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.JTextField;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingConstants;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Quick settings (FR-027). Every control reads from and writes to {@link ConfigManager}, so the panel and
 * the config screen share one source of truth (FR-028). EDT only; never touches the client.
 */
public class ActivityNotifierPanel extends PluginPanel
{
	private static final int SPINNER_WIDTH = 72;
	private static final int MAX_DELAY_MS = 600_000;
	private static final int DELAY_STEP_MS = 100;
	private static final int MAX_POINTS = 9_999;
	private static final int MAX_PERCENT = 100;
	private static final String NO_ANIMATION = "-";

	private final ConfigManager configManager;
	private final ActivityNotifierConfig config;

	private final JSpinner baseDelay = spinner(0, MAX_DELAY_MS, DELAY_STEP_MS);
	private final JCheckBox chatSignals = new JCheckBox("Chat messages");
	private final JCheckBox notificationSignals = new JCheckBox("RuneLite notification");
	private final Map<Detector, JCheckBox> detectorBoxes = new EnumMap<>(Detector.class);
	private final Map<Detector, JSpinner> delaySpinners = new EnumMap<>(Detector.class);
	private final Map<ResourceType, JCheckBox> resourceBoxes = new EnumMap<>(ResourceType.class);
	private final Map<ResourceType, JSpinner> thresholdSpinners = new EnumMap<>(ResourceType.class);
	private final JCheckBox damageBox = new JCheckBox("Damage taken");
	private final JSpinner damageMinimum = spinner(1, MAX_POINTS, 1);
	private final JTextField lastAnimationId = new JTextField(NO_ANIMATION);
	private final JLabel lastAnimationStatus = new JLabel();

	/**
	 * The last animation the player started, for finding IDs to add to Custom animation IDs; -1 until the
	 * first one.
	 */
	private int lastAnimation = -1;

	/**
	 * Set while {@link #refresh} copies config into the controls, so that doesn't write config back.
	 */
	private boolean refreshing;

	public ActivityNotifierPanel(ConfigManager configManager, ActivityNotifierConfig config)
	{
		this.configManager = configManager;
		this.config = config;

		setLayout(new GridBagLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.gridy = 0;
		c.weightx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.anchor = GridBagConstraints.NORTH;

		add(title("Activity Notifier"), c);
		c.gridy++;

		add(section("General", "ms", generalRows()), c);
		c.gridy++;
		add(section("Signals", null, signalsRows()), c);
		c.gridy++;
		add(section("General detectors", "Extra ms", detectorRows(Detector.Group.GENERAL)), c);
		c.gridy++;
		add(section("Specific activities", "Extra ms", detectorRows(Detector.Group.SPECIFIC)), c);
		c.gridy++;
		add(section("Resource alerts", "Threshold", resourceRows()), c);
		c.gridy++;
		add(syncNote(), c);
		c.gridy++;

		// push everything to the top
		c.weighty = 1;
		add(new JPanel(), c);

		refresh();
	}

	/**
	 * Re-reads every control from config (config changed elsewhere, or profile switched).
	 */
	public void refresh()
	{
		refreshing = true;
		try
		{
			baseDelay.setValue(Math.max(0, config.baseDelay()));
			chatSignals.setSelected(config.chatSignals());
			notificationSignals.setSelected(config.notificationSignals().isEnabled());
			for (Detector detector : Detector.values())
			{
				detectorBoxes.get(detector).setSelected(detector.isEnabled(configManager));
				delaySpinners.get(detector).setValue(detector.extraDelayMs(configManager));
			}
			for (ResourceType type : ResourceType.values())
			{
				resourceBoxes.get(type).setSelected(type.isEnabled(configManager));
				thresholdSpinners.get(type).setValue(type.threshold(configManager));
			}
			damageBox.setSelected(config.alertDamage());
			damageMinimum.setValue(Math.max(1, config.damageThreshold()));
			// the custom list may have changed, which changes how the last animation counts
			showLastAnimation();
		}
		finally
		{
			refreshing = false;
		}
	}

	/**
	 * Shows the animation the player just started. Called on the EDT.
	 */
	public void setLastAnimation(int animation)
	{
		lastAnimation = animation;
		showLastAnimation();
	}

	private void showLastAnimation()
	{
		if (lastAnimation == -1)
		{
			lastAnimationId.setText(NO_ANIMATION);
			lastAnimationStatus.setText("None yet");
			return;
		}

		lastAnimationId.setText(String.valueOf(lastAnimation));
		String countedAs = CustomAnimations.countedAs(lastAnimation, CustomAnimations.parse(config.customAnimationIds()));
		lastAnimationStatus.setText(CustomAnimations.NOT_COUNTED.equals(countedAs) ? countedAs : "Counts as " + countedAs);
	}

	private JPanel generalRows()
	{
		JLabel label = new JLabel("Base delay");
		label.setToolTipText("How long no activity must be seen before you count as inactive, before extra delays");
		baseDelay.setToolTipText("Base delay, in milliseconds");
		baseDelay.addChangeListener(e -> set("baseDelay", baseDelay.getValue()));

		JPanel rows = rowsPanel();
		addRow(rows, 0, label, baseDelay);
		return rows;
	}

	private JPanel signalsRows()
	{
		chatSignals.setToolTipText("Send signals as filtered game messages (Watchdog: Game Message alert, type Spam or Any)");
		chatSignals.addActionListener(e -> set("chatSignals", chatSignals.isSelected()));

		notificationSignals.setToolTipText("Send signals as RuneLite notifications (Watchdog: Notification Fired alert)");
		// keep the user's other notification options (sound, tray, focus) and only flip enabled
		notificationSignals.addActionListener(e ->
			set("notificationSignals", config.notificationSignals().withEnabled(notificationSignals.isSelected())));

		JPanel rows = rowsPanel();
		addRow(rows, 0, chatSignals, null);
		addRow(rows, 1, notificationSignals, null);
		return rows;
	}

	private JPanel detectorRows(Detector.Group group)
	{
		JPanel rows = rowsPanel();
		int row = 0;
		for (Detector detector : Detector.values())
		{
			if (detector.getGroup() != group)
			{
				continue;
			}

			JCheckBox box = new JCheckBox(detector.getDisplayName() + (detector.isBeta() ? " (beta)" : ""));
			box.addActionListener(e -> set(detector.getEnabledKey(), box.isSelected()));

			JSpinner spinner = spinner(0, MAX_DELAY_MS, DELAY_STEP_MS);
			spinner.setToolTipText("Extra delay for " + detector.getDisplayName() + ", in milliseconds");
			spinner.addChangeListener(e -> set(detector.getDelayKey(), spinner.getValue()));

			detectorBoxes.put(detector, box);
			delaySpinners.put(detector, spinner);
			addRow(rows, row++, box, spinner);
		}

		if (group == Detector.Group.GENERAL)
		{
			// read-only, but selectable so the ID can be copied into Custom animation IDs
			String tooltip = "The last animation you played, and whether it counts as activity. "
				+ "Copy the ID into Custom animation IDs to make it count";
			JLabel label = new JLabel("Last animation");
			label.setToolTipText(tooltip);
			lastAnimationId.setEditable(false);
			lastAnimationId.setHorizontalAlignment(JTextField.RIGHT);
			lastAnimationId.setPreferredSize(new Dimension(SPINNER_WIDTH, lastAnimationId.getPreferredSize().height));
			lastAnimationId.setToolTipText(tooltip);
			lastAnimationStatus.setFont(FontManager.getRunescapeSmallFont());
			lastAnimationStatus.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			lastAnimationStatus.setToolTipText(tooltip);
			addRow(rows, row++, label, lastAnimationId);
			addRow(rows, row++, lastAnimationStatus, null);
		}
		return rows;
	}

	private JPanel resourceRows()
	{
		JPanel rows = rowsPanel();
		int row = 0;
		for (ResourceType type : ResourceType.values())
		{
			JCheckBox box = new JCheckBox(type.getAlertKeyword());
			box.addActionListener(e -> set(type.getEnabledKey(), box.isSelected()));

			boolean percent = type.getUnit() == ResourceType.Unit.PERCENT;
			JSpinner spinner = spinner(0, percent ? MAX_PERCENT : MAX_POINTS, 1);
			spinner.setToolTipText(type.getAlertKeyword() + " threshold" + (percent ? ", in percent" : ""));
			spinner.addChangeListener(e -> set(type.getThresholdKey(), spinner.getValue()));

			resourceBoxes.put(type, box);
			thresholdSpinners.put(type, spinner);
			addRow(rows, row++, box, spinner);
		}

		// cooldown and damage over time stay in the settings page
		damageBox.setToolTipText("Send a signal when you take damage of at least the minimum");
		damageBox.addActionListener(e -> set("alertDamage", damageBox.isSelected()));
		damageMinimum.setToolTipText("Minimum damage of a single hit");
		damageMinimum.addChangeListener(e -> set("damageThreshold", damageMinimum.getValue()));
		addRow(rows, row++, damageBox, damageMinimum);
		return rows;
	}

	private <T> void set(String key, T value)
	{
		if (!refreshing)
		{
			configManager.setConfiguration(ActivityNotifierConfig.GROUP, key, value);
		}
	}

	private static JSpinner spinner(int min, int max, int step)
	{
		JSpinner spinner = new JSpinner(new SpinnerNumberModel(min, min, max, step));
		Dimension size = spinner.getPreferredSize();
		spinner.setPreferredSize(new Dimension(SPINNER_WIDTH, size.height));
		return spinner;
	}

	private static JLabel title(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(ColorScheme.BRAND_ORANGE);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		return label;
	}

	/**
	 * RuneLite's settings page only re-reads values when it is opened, so changes made here show up
	 * there the next time it is opened. They still apply immediately.
	 */
	private static JLabel syncNote()
	{
		JLabel note = new JLabel("<html>Changes apply immediately. If the plugin's settings page is open, "
			+ "reopen it to see them there.</html>");
		note.setFont(FontManager.getRunescapeSmallFont());
		note.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		note.setBorder(BorderFactory.createEmptyBorder(10, 0, 0, 0));
		return note;
	}

	private static JPanel section(String name, String columnHeader, JPanel rows)
	{
		JPanel header = new JPanel(new BorderLayout());
		header.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(0, 0, 3, 0)));

		JLabel title = new JLabel(name);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.TEXT_COLOR);
		header.add(title, BorderLayout.WEST);

		if (columnHeader != null)
		{
			JLabel column = new JLabel(columnHeader, SwingConstants.RIGHT);
			column.setFont(FontManager.getRunescapeSmallFont());
			column.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			header.add(column, BorderLayout.EAST);
		}

		JPanel section = new JPanel(new BorderLayout());
		section.setBorder(BorderFactory.createEmptyBorder(10, 0, 0, 0));
		section.add(header, BorderLayout.NORTH);
		section.add(rows, BorderLayout.CENTER);
		return section;
	}

	private static JPanel rowsPanel()
	{
		JPanel rows = new JPanel(new GridBagLayout());
		rows.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		return rows;
	}

	private static void addRow(JPanel rows, int row, JComponent left, JComponent right)
	{
		GridBagConstraints c = new GridBagConstraints();
		c.gridy = row;
		// without a right-hand control, the left one can use the full width
		c.gridwidth = right == null ? 2 : 1;
		c.insets = new Insets(1, 0, 1, 0);
		c.anchor = GridBagConstraints.WEST;

		c.gridx = 0;
		c.weightx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		rows.add(left, c);

		if (right != null)
		{
			c.gridx = 1;
			c.weightx = 0;
			c.fill = GridBagConstraints.NONE;
			c.anchor = GridBagConstraints.EAST;
			rows.add(right, c);
		}
	}
}

package com.activitynotifier.warnings;

import com.activitynotifier.signals.Signal;
import java.time.Duration;
import java.time.Instant;
import java.util.Optional;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Constants;

/**
 * Single warnings before the idle logout and the six-hour session limit (FR-017, FR-018, research R9).
 * Thresholds match core Idle Notifier. Has no client dependency. Client thread only.
 */
@Slf4j
public class LogoutWarningTracker
{
	/**
	 * Warn this long before the idle logout: 20 seconds, in client ticks.
	 */
	static final int IDLE_BUFFER_TICKS = 20_000 / Constants.CLIENT_TICK_LENGTH;

	static final Duration SIX_HOUR_WARNING_AFTER = Duration.ofMinutes(340);

	/**
	 * Armed once idle ticks are seen below the warning point, so a warning needs a period of input first.
	 */
	private boolean idleArmed;

	private Instant loginAt;
	private boolean sessionArmed;

	/**
	 * @param idleTicks client ticks since the last mouse or keyboard input
	 * @param idleTimeoutTicks client ticks of idling before the game logs out
	 */
	public Optional<Signal> checkIdle(int idleTicks, int idleTimeoutTicks)
	{
		if (idleTicks < idleTimeoutTicks - IDLE_BUFFER_TICKS)
		{
			idleArmed = true;
			return Optional.empty();
		}

		if (!idleArmed)
		{
			return Optional.empty();
		}

		idleArmed = false;
		log.debug("Idle logout warning ({} of {} idle ticks)", idleTicks, idleTimeoutTicks);
		return Optional.of(Signal.idleLogout());
	}

	/**
	 * Starts the six-hour session timer.
	 */
	public void onLogin(Instant now)
	{
		loginAt = now;
		sessionArmed = true;
	}

	public Optional<Signal> checkSession(Instant now)
	{
		if (!sessionArmed || Duration.between(loginAt, now).compareTo(SIX_HOUR_WARNING_AFTER) < 0)
		{
			return Optional.empty();
		}

		sessionArmed = false;
		log.debug("Six hour logout warning (logged in at {})", loginAt);
		return Optional.of(Signal.sixHour());
	}

	/**
	 * Disarms both warnings (logout).
	 */
	public void reset()
	{
		idleArmed = false;
		loginAt = null;
		sessionArmed = false;
	}
}

