package com.activitynotifier.detection;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.google.common.collect.ImmutableSet;
import java.util.Set;
import net.runelite.api.gameval.AnimationID;
import org.junit.Test;

public class CustomAnimationsTest
{
	@Test
	public void parsesCommaSeparatedIds()
	{
		assertEquals(ImmutableSet.of(5216, 13149), CustomAnimations.parse("5216, 13149"));
	}

	@Test
	public void emptyOrNullTextGivesEmptySet()
	{
		assertTrue(CustomAnimations.parse("").isEmpty());
		assertTrue(CustomAnimations.parse(null).isEmpty());
	}

	@Test(expected = UnsupportedOperationException.class)
	public void parsedSetIsImmutable()
	{
		CustomAnimations.parse("5216").add(1);
	}

	@Test
	public void forgivesSpacesEmptyEntriesDuplicatesAndJunk()
	{
		assertEquals(ImmutableSet.of(5216, 13149), CustomAnimations.parse(" 5216 ,,13149, 5216, abc, -5 ,"));
	}

	@Test
	public void ignoresEntriesThatAreNotWholeNonNegativeNumbers()
	{
		assertTrue(CustomAnimations.parse("52l6").isEmpty());
		assertTrue(CustomAnimations.parse("1.5").isEmpty());
		assertTrue(CustomAnimations.parse("-1").isEmpty());
		assertTrue(CustomAnimations.parse("99999999999").isEmpty());
	}

	@Test
	public void acceptsZeroAndLeadingPlus()
	{
		assertEquals(ImmutableSet.of(0), CustomAnimations.parse("0"));
		assertEquals(ImmutableSet.of(5216), CustomAnimations.parse("+5216"));
	}

	@Test
	public void onlyCommasSeparateEntries()
	{
		assertTrue(CustomAnimations.parse("5216 13149").isEmpty());
	}

	@Test
	public void separatorsOrSpacesAloneGiveEmptySet()
	{
		assertTrue(CustomAnimations.parse(",").isEmpty());
		assertTrue(CustomAnimations.parse("  ").isEmpty());
	}

	@Test
	public void parsesLongLists()
	{
		StringBuilder text = new StringBuilder();
		for (int id = 1; id <= 300; id++)
		{
			text.append(id).append(", ");
		}
		assertEquals(300, CustomAnimations.parse(text.toString()).size());
	}

	@Test
	public void helmAnimationsCountAsSailingEvenIfListed()
	{
		int helm = AnimationCatalog.HELM_ANIMATIONS.iterator().next();
		assertEquals("Sailing", CustomAnimations.countedAs(helm, ImmutableSet.of()));
		assertEquals("Sailing", CustomAnimations.countedAs(helm, ImmutableSet.of(helm)));
	}

	@Test
	public void builtInAnimationsKeepTheirNameEvenIfListed()
	{
		int axe = AnimationID.HUMAN_WOODCUTTING_BRONZE_AXE;
		assertEquals("Woodcutting", CustomAnimations.countedAs(axe, ImmutableSet.of()));
		assertEquals("Woodcutting", CustomAnimations.countedAs(axe, ImmutableSet.of(axe)));
		assertEquals("Animation", CustomAnimations.countedAs(AnimationID.MILKIT, ImmutableSet.of()));
	}

	@Test
	public void listedAnimationsCountAsAnimation()
	{
		assertEquals("Not counted", CustomAnimations.countedAs(5216, ImmutableSet.of()));
		assertEquals("Animation", CustomAnimations.countedAs(5216, ImmutableSet.of(5216)));
	}

	@Test
	public void idsFollowsTheText()
	{
		CustomAnimations custom = new CustomAnimations();
		assertEquals(ImmutableSet.of(5216), custom.ids("5216"));
		assertEquals(ImmutableSet.of(5216), custom.ids("5216"));
		assertEquals(ImmutableSet.of(13149), custom.ids("13149"));
	}

	@Test
	public void removedIdStopsCounting()
	{
		CustomAnimations custom = new CustomAnimations();
		assertTrue(custom.ids("5216").contains(5216));
		assertFalse(custom.ids("").contains(5216));
		Set<Integer> ids = custom.ids("13149");
		assertTrue(ids.contains(13149));
		assertFalse(ids.contains(5216));
	}

	@Test
	public void unchangedTextIsNotReparsed()
	{
		CustomAnimations custom = new CustomAnimations();
		Set<Integer> first = custom.ids(new String("5216"));
		assertSame(first, custom.ids(new String("5216")));
	}

	@Test
	public void nullTextIsTreatedAsEmpty()
	{
		CustomAnimations custom = new CustomAnimations();
		custom.ids("5216");
		assertTrue(custom.ids(null).isEmpty());
	}
}

package com.activitynotifier.detection;

import java.util.EnumMap;
import java.util.Map;
import java.util.Optional;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import org.junit.Before;
import org.junit.Test;

public class XpGainTrackerTest
{
	private XpGainTracker tracker;

	@Before
	public void setUp()
	{
		tracker = new XpGainTracker();
	}

	private static Map<Skill, Integer> xp(Skill skill, int value)
	{
		Map<Skill, Integer> map = new EnumMap<>(Skill.class);
		map.put(skill, value);
		return map;
	}

	@Test
	public void silentBeforeSeed()
	{
		// the login burst of StatChanged events arrives before the cache is seeded
		assertFalse(tracker.onXp(Skill.AGILITY, 1000, 1).isPresent());
		assertFalse(tracker.onXp(Skill.AGILITY, 2000, 1).isPresent());
	}

	@Test
	public void unchangedXpAfterSeedIsSilent()
	{
		tracker.seed(xp(Skill.AGILITY, 1000));
		assertFalse(tracker.onXp(Skill.AGILITY, 1000, 1).isPresent());
	}

	@Test
	public void firstSampleOfUnseededSkillIsSilent()
	{
		tracker.seed(xp(Skill.AGILITY, 1000));
		assertFalse(tracker.onXp(Skill.MINING, 5000, 1).isPresent());
		assertEquals(Optional.of(Skill.MINING), tracker.onXp(Skill.MINING, 5035, 1));
	}

	@Test
	public void gainAtOrAboveThresholdReturnsSkill()
	{
		tracker.seed(xp(Skill.AGILITY, 1000));
		assertEquals(Optional.of(Skill.AGILITY), tracker.onXp(Skill.AGILITY, 1010, 10));
		assertEquals(Optional.of(Skill.AGILITY), tracker.onXp(Skill.AGILITY, 1100, 10));
	}

	@Test
	public void gainBelowThresholdIsIgnored()
	{
		tracker.seed(xp(Skill.HITPOINTS, 1000));
		assertFalse(tracker.onXp(Skill.HITPOINTS, 1004, 5).isPresent());
		// the cache still advances, so small drops never add up
		assertFalse(tracker.onXp(Skill.HITPOINTS, 1008, 5).isPresent());
	}

	@Test
	public void resetRequiresReseeding()
	{
		tracker.seed(xp(Skill.AGILITY, 1000));
		tracker.reset();
		assertFalse(tracker.onXp(Skill.AGILITY, 1500, 1).isPresent());

		tracker.seed(xp(Skill.AGILITY, 1500));
		assertEquals(Optional.of(Skill.AGILITY), tracker.onXp(Skill.AGILITY, 1600, 1));
	}
}

package com.activitynotifier.resources;

import com.activitynotifier.signals.Signal;
import com.activitynotifier.signals.SignalFormatter;
import com.activitynotifier.signals.SignalType;
import java.util.Optional;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ResourceAlertTrackerTest
{
	private final ResourceAlertTracker hitpoints = new ResourceAlertTracker(ResourceType.HITPOINTS);
	private final ResourceAlertTracker special = new ResourceAlertTracker(ResourceType.SPECIAL_ATTACK);

	@Test
	public void firstSampleIsSilent()
	{
		assertFalse("below threshold at login", hitpoints.sample(5, 10).isPresent());
		assertEquals(ResourceAlertTracker.State.ALERTED, hitpoints.getState());

		ResourceAlertTracker prayer = new ResourceAlertTracker(ResourceType.PRAYER);
		assertFalse(prayer.sample(50, 10).isPresent());
		assertEquals(ResourceAlertTracker.State.NORMAL, prayer.getState());
	}

	@Test
	public void lowCrossingAlertsOnceThenRecoversOnce()
	{
		hitpoints.sample(50, 10);

		Optional<Signal> alert = hitpoints.sample(10, 10);
		assertTrue("at the threshold counts as low", alert.isPresent());
		assertEquals(SignalType.RESOURCE_ALERT, alert.get().getType());
		assertEquals("Activity Notifier: Low hitpoints - 10 (threshold 10)",
			SignalFormatter.format(alert.get(), "{value} (threshold {threshold})"));

		assertFalse("fluctuating below", hitpoints.sample(7, 10).isPresent());
		assertFalse(hitpoints.sample(9, 10).isPresent());

		Optional<Signal> recovered = hitpoints.sample(34, 10);
		assertTrue(recovered.isPresent());
		assertEquals(SignalType.RESOURCE_RECOVERED, recovered.get().getType());
		assertEquals("Activity Notifier: Hitpoints recovered - 34",
			SignalFormatter.format(recovered.get(), "{value}"));

		assertFalse(hitpoints.sample(40, 10).isPresent());
	}

	@Test
	public void highCrossingIsMirrored()
	{
		special.sample(50, 100);

		Optional<Signal> restored = special.sample(100, 100);
		assertTrue(restored.isPresent());
		assertEquals("Activity Notifier: Special attack restored - 100% (threshold 100%)",
			SignalFormatter.format(restored.get(), "{value} (threshold {threshold})"));
		assertFalse(special.sample(100, 100).isPresent());

		Optional<Signal> used = special.sample(50, 100);
		assertTrue(used.isPresent());
		assertEquals("Activity Notifier: Special attack used - 50%", SignalFormatter.format(used.get(), "{value}"));
		assertFalse(special.sample(60, 100).isPresent());
	}

	@Test
	public void clearWhileAlertedRecoversOnce()
	{
		hitpoints.sample(50, 10);
		hitpoints.sample(5, 10);

		Optional<Signal> cleared = hitpoints.clear("Detection paused");
		assertTrue(cleared.isPresent());
		assertEquals(SignalType.RESOURCE_RECOVERED, cleared.get().getType());
		assertEquals("Activity Notifier: Hitpoints recovered - Detection paused",
			SignalFormatter.format(cleared.get(), "{value}"));
		assertEquals(ResourceAlertTracker.State.UNKNOWN, hitpoints.getState());

		assertFalse(hitpoints.clear("Detection paused").isPresent());
	}

	@Test
	public void clearWhileNormalOrUnknownIsSilent()
	{
		assertFalse(hitpoints.clear("Plugin stopped").isPresent());
		hitpoints.sample(50, 10);
		assertFalse(hitpoints.clear("Plugin stopped").isPresent());
	}

	@Test
	public void turningAlertOffWhileAlertedClears()
	{
		hitpoints.sample(50, 10);
		hitpoints.sample(5, 10);
		assertTrue(hitpoints.clear(ResourceAlertTracker.CLEARED_ALERT_OFF).isPresent());

		// turned back on while still low: silent, like a fresh login
		assertFalse(hitpoints.sample(5, 10).isPresent());
	}

	@Test
	public void resetIsSilent()
	{
		hitpoints.sample(50, 10);
		hitpoints.sample(5, 10);
		hitpoints.reset();
		assertEquals(ResourceAlertTracker.State.UNKNOWN, hitpoints.getState());
		assertFalse(hitpoints.sample(50, 10).isPresent());
	}
}

package com.activitynotifier.signals;

import com.activitynotifier.resources.ResourceType;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import org.junit.Test;

public class SignalFormatterTest
{
	/**
	 * Resource keywords exactly as in contracts/signals.md, to catch an accidental keyword change.
	 */
	private static final List<String> CONTRACT_RESOURCE_KEYWORDS = Arrays.asList(
		"Low hitpoints", "Hitpoints recovered",
		"Low prayer", "Prayer recovered",
		"Low run energy", "Run energy recovered",
		"Run energy restored", "Run energy used",
		"Low oxygen", "Oxygen recovered",
		"Special attack restored", "Special attack used"
	);

	private static List<String> resourceKeywords()
	{
		List<String> keywords = new ArrayList<>();
		for (ResourceType type : ResourceType.values())
		{
			keywords.add(type.getAlertKeyword());
			keywords.add(type.getRecoveredKeyword());
		}
		return keywords;
	}

	private static List<String> allHeads()
	{
		List<String> heads = new ArrayList<>();
		for (SignalType type : SignalType.values())
		{
			if (type.getKeyword() != null)
			{
				heads.add(SignalFormatter.head(type.getKeyword()));
			}
		}
		for (String keyword : resourceKeywords())
		{
			heads.add(SignalFormatter.head(keyword));
		}
		return heads;
	}

	@Test
	public void resourceKeywordsMatchContract()
	{
		assertEquals(CONTRACT_RESOURCE_KEYWORDS, resourceKeywords());
	}

	@Test
	public void headsContainNoGlobSpecialCharacters()
	{
		for (String head : allHeads())
		{
			for (char c : "[]{},!\\".toCharArray())
			{
				assertFalse("'" + head + "' contains '" + c + "'", head.indexOf(c) >= 0);
			}
		}
	}

	@Test
	public void noHeadIsSubstringOfAnother()
	{
		List<String> heads = allHeads();
		for (String a : heads)
		{
			for (String b : heads)
			{
				if (!a.equals(b))
				{
					assertFalse("'" + a + "' is contained in '" + b + "'",
						b.toLowerCase(Locale.ROOT).contains(a.toLowerCase(Locale.ROOT)));
				}
			}
		}
	}

	@Test
	public void formatsInactiveWithDefaultTemplate()
	{
		assertEquals("Activity Notifier: Inactive - Woodcutting",
			SignalFormatter.format(Signal.inactive("Woodcutting"), "{activity}"));
	}

	@Test
	public void formatsActiveWithDuration()
	{
		assertEquals("Activity Notifier: Active - Woodcutting (inactive for 1m 23s)",
			SignalFormatter.format(Signal.active("Woodcutting", Duration.ofSeconds(83)), "{activity} (inactive for {duration})"));
	}

	@Test
	public void clearedSignalIgnoresTemplate()
	{
		assertEquals("Activity Notifier: Active - Detection paused",
			SignalFormatter.format(Signal.cleared("Detection paused"), "{activity} (inactive for {duration})"));
	}

	@Test
	public void emptyTemplateRendersHeadOnly()
	{
		assertEquals("Activity Notifier: Inactive", SignalFormatter.format(Signal.inactive("Mining"), ""));
		assertEquals("Activity Notifier: Inactive", SignalFormatter.format(Signal.inactive("Mining"), "   "));
		assertEquals("Activity Notifier: Inactive", SignalFormatter.format(Signal.inactive("Mining"), null));
	}

	@Test
	public void unknownTokensAreLeftAsIs()
	{
		assertEquals("Activity Notifier: Inactive - Mining {nope}",
			SignalFormatter.format(Signal.inactive("Mining"), "{activity} {nope}"));
	}

	@Test
	public void resourceTokens()
	{
		Signal signal = Signal.builder()
			.type(SignalType.RESOURCE_ALERT)
			.keyword("Low hitpoints")
			.resource("Hitpoints")
			.value("9")
			.threshold("10")
			.build();
		assertEquals("Activity Notifier: Low hitpoints - Hitpoints 9 (threshold 10)",
			SignalFormatter.format(signal, "{resource} {value} (threshold {threshold})"));
	}

	@Test
	public void damageTakenTokens()
	{
		// the example rows of specs/done/002-damage-notifier/contracts/signals.md
		assertEquals("Activity Notifier: Damage taken - 12",
			SignalFormatter.format(Signal.damageTaken(12, 1, 38), "{damage}"));
		assertEquals("Activity Notifier: Damage taken - 12 damage, 38 HP left",
			SignalFormatter.format(Signal.damageTaken(12, 1, 38), "{damage} damage, {hitpoints} HP left"));
		assertEquals("Activity Notifier: Damage taken - 20 (minimum 15)",
			SignalFormatter.format(Signal.damageTaken(20, 15, 50), "{damage} (minimum {threshold})"));
		assertEquals("Activity Notifier: Damage taken",
			SignalFormatter.format(Signal.damageTaken(7, 1, 92), ""));
	}

	@Test
	public void damageTakenLeavesOtherTokens()
	{
		assertEquals("Activity Notifier: Damage taken - 5 {activity}",
			SignalFormatter.format(Signal.damageTaken(5, 1, 10), "{damage} {activity}"));
	}

	@Test
	public void formatsDurations()
	{
		assertEquals("0s", SignalFormatter.formatDuration(Duration.ZERO));
		assertEquals("45s", SignalFormatter.formatDuration(Duration.ofSeconds(45)));
		assertEquals("1m 23s", SignalFormatter.formatDuration(Duration.ofSeconds(83)));
		assertEquals("5m 0s", SignalFormatter.formatDuration(Duration.ofMinutes(5)));
		assertEquals("1h 2m", SignalFormatter.formatDuration(Duration.ofMinutes(62).plusSeconds(30)));
		assertEquals("0s", SignalFormatter.formatDuration(Duration.ofSeconds(-5)));
	}
}

package com.activitynotifier.warnings;

import com.activitynotifier.signals.Signal;
import com.activitynotifier.signals.SignalType;
import java.time.Duration;
import java.time.Instant;
import java.util.Optional;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class LogoutWarningTrackerTest
{
	private static final int TIMEOUT = 15_000;
	private static final int WARN_AT = TIMEOUT - LogoutWarningTracker.IDLE_BUFFER_TICKS;
	private static final Instant LOGIN = Instant.parse("2026-10-12T12:00:00Z");

	private final LogoutWarningTracker tracker = new LogoutWarningTracker();

	@Test
	public void bufferIsTwentySeconds()
	{
		assertEquals(1000, LogoutWarningTracker.IDLE_BUFFER_TICKS);
	}

	@Test
	public void idleWarnsOnceThenRearmsAfterInput()
	{
		assertFalse(tracker.checkIdle(0, TIMEOUT).isPresent());
		assertFalse(tracker.checkIdle(WARN_AT - 1, TIMEOUT).isPresent());

		Optional<Signal> warning = tracker.checkIdle(WARN_AT, TIMEOUT);
		assertTrue(warning.isPresent());
		assertEquals(SignalType.IDLE_LOGOUT, warning.get().getType());
		assertFalse("only once", tracker.checkIdle(WARN_AT + 500, TIMEOUT).isPresent());

		// input resets the client's idle ticks
		assertFalse(tracker.checkIdle(3, TIMEOUT).isPresent());
		assertTrue(tracker.checkIdle(WARN_AT, TIMEOUT).isPresent());
	}

	@Test
	public void idleDoesNotWarnWithoutSeeingActivityFirst()
	{
		// e.g. enabled mid-session while already idle past the warning point
		assertFalse(tracker.checkIdle(WARN_AT + 10, TIMEOUT).isPresent());
	}

	@Test
	public void sixHourWarnsOnceAt340Minutes()
	{
		tracker.onLogin(LOGIN);
		assertFalse(tracker.checkSession(LOGIN.plus(Duration.ofMinutes(339))).isPresent());

		Optional<Signal> warning = tracker.checkSession(LOGIN.plus(Duration.ofMinutes(340)));
		assertTrue(warning.isPresent());
		assertEquals(SignalType.SIX_HOUR, warning.get().getType());
		assertFalse(tracker.checkSession(LOGIN.plus(Duration.ofMinutes(345))).isPresent());
	}

	@Test
	public void sixHourNeedsALogin()
	{
		assertFalse(tracker.checkSession(LOGIN.plus(Duration.ofHours(10))).isPresent());
	}

	@Test
	public void nextLoginRearmsSixHour()
	{
		tracker.onLogin(LOGIN);
		assertTrue(tracker.checkSession(LOGIN.plus(Duration.ofMinutes(340))).isPresent());

		Instant relogin = LOGIN.plus(Duration.ofHours(6));
		tracker.onLogin(relogin);
		assertFalse(tracker.checkSession(relogin.plus(Duration.ofMinutes(1))).isPresent());
		assertTrue(tracker.checkSession(relogin.plus(Duration.ofMinutes(340))).isPresent());
	}

	@Test
	public void resetDisarmsBoth()
	{
		tracker.onLogin(LOGIN);
		tracker.checkIdle(0, TIMEOUT);
		tracker.reset();

		assertFalse(tracker.checkIdle(WARN_AT, TIMEOUT).isPresent());
		assertFalse(tracker.checkSession(LOGIN.plus(Duration.ofMinutes(340))).isPresent());
	}
}
